# ১ম অধ্যায়: প্রত্যুপকার (ঈশ্বরচন্দ্র বিদ্যাসাগর)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: ঈশ্বরচন্দ্র বিদ্যাসাগর*

---

### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি: ঈশ্বরচন্দ্র বিদ্যাসাগর ভারতের পশ্চিমবঙ্গের মেদিনীপুর জেলার বীরসিংহ গ্রামে ২৬শে
সেপ্টেম্বর, ১৮২০ খিষ্টাব্দে জনুগ্রহণ করেন । তার মূল নাম ঈশ্বরচন্দ্র বন্দ্যোপাধ্যায় । বিদ্যাসাগর" তার উপাধি ।
তিনি ছিলেন কলকাতা সংস্কৃত কলেজের ছাত্র। তিনি প্রথমে সংস্কৃত ও পরে ইংরেজি ভাষায় পাপ্ডিত্য অর্জন
করেন। দানশীলতার জন্য তিনি “দয়ার সাগর" নামেও পরিচিত । একাধারে পঞ্তিত, শিক্ষাবিদ, সমাজ-সংস্কারক
ও খ্যাতনামা লেখক হিসেবে প্রতিষ্ঠা লাভ করেছিলেন তিনি । সুশৃঙ্খল পদবিন্যাস, যথাযথভাবে যতিচিহ্ন প্রয়োগ
এবং সাহিত্যিক গদ্য রচনার জন্য তাকে বাংলা গদ্যের জনক বলা হয়ে থাকে । বাংলা বর্ণমালাকে নতুন বিন্যাসে
সাজিয়ে ১৮৫৫ খিষ্টাব্দে বিদ্যাসাগর প্রকাশ করেন শিশুপাঠ্য বই বর্ণপরিচয়। ভাষা শিক্ষাদানের ক্ষেত্রে এ বই
আজও পথপ্রদর্শক বিবেচিত হয়। বেতাল পঞ্বিংশতি, ব্যাকরণ কৌমুদী, শকুন্তলা, বিধবা বিবাহ প্রচলিত
হওয়া উচিত কি না এতদ্ষয়ক প্রস্তাব, সীতার বনবাস, ত্রান্তিবিলাস প্রভৃতি তার প্রধান গ্রন্থ। ঈশ্বরচন্দ্র
বিদ্যাসাগর ১৮৯১ খিষ্টাব্দের ২৯শে জুলাই মৃত্যুবরণ করেন |

---

## 📖 মূল পাঠ (গদ্য)

প্রত্যুপকার

ঈশ্বরচন্দ্র বিদ্যাসাগর



আলী ইবনে আব্বাস নামে এক ব্যক্তি মামুন নামক খলিফার প্রিয়পাত্র ছিলেন । তিনি বলিয়া গিয়াছেন,

আমি একদিন অপরাহে খলিফার নিকটে বসিয়া আছি এমন সময়ে, হস্তপদবদ্ধ এক ব্যক্তি তাহার

সম্মুখে নীত হইলেন। খলিফা আমার প্রতি এই আজ্ঞা করিলেন, তুমি এ ব্যক্তিকে আপন আলয়ে লইয়া

গিয়া রুদ্ধ করিয়া রাখিবে এবং কল্য আমার নিকট উপস্থিত করিবে । তদীয় ভাব দর্শনে স্পষ্ট প্রতীত

হইল, তিনি এ ব্যক্তির উপর অত্যন্ত ক্রুদ্ধ হইয়াছেন। আমি তাহাকে আপন আলয়ে আনিয়া অতি

ধনের রি রাসিনাস, কারণ মণি ভিন পাইয়া যান, আমারে শির কোগে পতিত হইতে
[

কিয়ৎক্ষণ পরে, আমি তাহাকে জিজ্ঞাসিলাম, আপনার নিবাস কোথায়? তিনি বলিলেন, ডেমাস্কাস
আমার জন্যস্থান; এ নগরের যে অংশে বৃহৎ মসজিদ আছে, তথায় আমার বাস। আমি বলিলাম,
ডেমাস্কাস নগরের, বিশেষত যে অংশে আপনার বাস তাহার উপর, জগদীশ্বরের শুভদৃষ্টি থাকুক । এ
অংশের অধিবাসী এক ব্যক্তি একসময় আমার প্রাণদান দিয়াছিলেন।

আমার এই কথা শুনিয়া, তিনি সবিশেষ জানিবার নিমিত্ত, ইচ্ছা প্রকাশ করিলে, আমি বলিতে আরম্ত
করিলাম : বহু বৎসর পূর্বে ডেমাস্কাসের শাসনকর্তা পদচ্যুত হইলে, যিনি তদীয় পদে অধিষ্ঠিত হন,
আক্রমণ করিলেন। আমি প্রাণভয়ে পলাইয়া, এক সন্তান্ত লোকের বাড়িতে প্রবিষ্ট হইলাম এবং গৃহস্বামীর
নিকট গিয়া, অতি কাতর বচনে প্রার্থনা করিলাম, আপনি কৃপা করিয়া আমার প্রাণ রক্ষা করুন| আমার
্রার্থনাবাক্য শুনিয়া গৃহস্বামী আমায় অভয় প্রদান করিলেন । আমি তদীয় আবাসে, এক মাসকাল নির্ভয়ে
ও নিরাপদে অবস্থিতি করিলাম ।

একদিন আশ্রয়দাতা আমায় বলিলেন, এ সময়ে অনেক লোক বাগদাদ যাইতেছেন। স্বদেশে প্রতিগমনের
পক্ষে আপনি ইহা অপেক্ষা অধিক সুবিধার সময় পাইবেন না। আমি সম্মত হইলাম। আমার সঙ্গে
কিছুমাত্র অর্থ ছিল না, লঙ্জাবশত আমি তাহার নিকট সে কথা ব্যক্ত করিতে পারিলাম না। তিনি,

তিনি আমার জন্য যে সমস্ত উদ্যোগ করিয়া রাখিয়াছিলেন, প্রস্থান দিবসে তাহা দেখিয়া আমি বিস্ময়াপন্ন
হইলাম। একটি উৎকৃষ্ট অশ্ব সুসজ্জিত হইয়া আছে, আর একটি অশ্বের পৃষ্ঠে খাদ্যসামী স্থাপিত হইয়াছে,
আর পথে আমার পরিচর্যা করিবার নিমিত্ত, একটি ভূত্য প্রস্থানার্থে প্রস্তুত হইয়া রহিয়াছে। প্রস্থান সময়
উপস্থিত হইলে, সেই দয়াময়, সদাশয়, আশ্রয়দাতা আমার হস্তে একটি স্বর্ণমুদ্রার থলি দিলেন এবং আমাকে
যাত্রীদের নিকটে লইয়া গেলেন। তনুধ্যে যাহাদের সহিত তাহার আত্মীয়তা ছিল, তাহাদের সঙ্গে আলাপ
করাইয়া দিলেন। আমি আপনকার বসতি স্থানে এই সমস্ত উপকার প্রাপ্ত হইয়াছিলাম। এ জন্য পৃথিবীতে যত
স্থান আছে এ স্থান আমার সর্বাপেক্ষা প্রিয় ।

এই নির্দেশ করিয়া, দুঃখ প্রকাশপূর্বক আমি বলিলাম, আক্ষেপের বিষয় এই, আমি এ পর্যন্ত সেই দয়াময়
আশ্রয়দাতার কখনো কোনো উদ্দেশ পাইলাম না। যদি তাহার নিকট কোনো অংশে কৃতজ্ঞতা প্রদর্শনের
অবসর পাই, তাহা হইলে মৃত্যকালে আমার কোনো ক্ষোভ থাকে না। এই কথা শুনিবামাত্র, তিনি অতিশয়
আহ্রাদিত হইয়া বলিলেন, আপনার মনস্কাম পূর্ণ হইয়াছে । আপনি যে ব্যক্তির উল্লেখ করিলেন, সে এই। এই
হতভাগ্যই আপনাকে, এক মাসকাল আপন আলয়ে রাখিয়াছিল।

তাহার এই কথা শুনিয়া, আমি চমকিয়া উঠিলাম, সবিশেষ অভিনিবেশ সহকারে, কিয়ৎক্ষণ নিরীক্ষণ করিয়া,
হইতে লৌহশৃঙ্খল খুলিয়া দিলাম এবং কী দুর্ঘটনাক্রমে তিনি খলিফার কোপে পতিত হইয়াছেন, তাহা
জানিবার নিমিত্তে নিতান্ত ব্যথ হইলাম । তখন তিনি বলিলেন, কতিপয় নীচ প্রকৃতির লোক ঈর্ধাবশত শক্রতা
করিয়া খলিফার নিকট আমার ওপর উৎকট দোষারোপ করিয়াছে; তজ্জন্য তদীয় আদেশক্রমে হঠাৎ অবরুদ্ধ
ও এখানে আনীত হইয়াছিঃ আসিবার সময় স্ত্রী, পুত্র, কন্যাদিগের সহিত দেখা করিতে দেয় নাই; বোধ করি
আমার প্রাণদণ্ড হইবে । অতএব, আপনার নিকট বিনীত বাক্যে প্রার্থনা এই, আপনি অনুগ্রহ করিয়া আমার
পরিবারবর্ণের নিকট এই সংবাদ পাঠাইয়া দিবেন । তাহা হইলে আমি যথেষ্ট উপকৃত হইব।

তাহার এই প্রার্থনা শুনিয়া আমি বলিলাম, না, না, আপনি এক মুহূর্তের জন্যও প্রাণনাশের আশঙ্কা করিবেন
না; আপনি এই মুহূর্ত হইতে স্বাধীন; এই বলিয়া পাথেয়স্বরূপ সহস্র স্বর্ণমুদ্রার একটি থলি তাহার হস্তে দিয়া
বলিলাম, আপনি অবিলম্বে প্রস্থান করুন এবং গ্রেহাস্পদ পরিবারবর্ণের সহিত মিলিত হইয়া সংসারযাত্রা
সম্পন্ন করুন। আপনাকে ছাড়িয়া দিলাম, এ জন্য আমার ওপর খলিফার মর্মান্তিক ক্রোধ ও দ্বেষ জন্মিবে,
তাহাতে সন্দেহ নাই। কিন্তু যদি আপনার প্রাণ রক্ষা করিতে পারি, তাহা হইলে সে জন্য আমি অণুমাত্র
দুঃখিত হইব না।



আমার প্রস্তাব শুনিয়া তিনি বলিলেন, আপনি যাহা বলিতেছেন, আমি কখনই তাহাতে সম্মত হইতে পারিব
না। আমি এত নীচাশয় ও স্বার্থপর নহি যে, কিছুকাল পূর্বে, যে প্রাণের রক্ষা করিয়াছি, আপন প্রাণরক্ষার্থে
এক্ষণে সেই প্রাণের বিনাশের কারণ হইব । তাহা কখনও হইবে না। যাহাতে খলিফা আমার ওপর অক্রোধ
হন, আপনি দয়া করিয়া তাহার যথোপযুক্ত চেষ্টা দেখুনঃ তাহা হইলেই আপনার প্রকৃত কৃতজ্ঞতা প্রদর্শন করা
হইবে । যদি আপনার চেষ্টা সফল না হয়, তাহা হইলেও আমার কোনো ক্ষোভ থাকিবে না।

পরদিন প্রাতঃকালে আমি খলিফার নিকট উপস্থিত হইলাম । তিনি জিজ্ঞাসা করিলেন, সে লোকটি কোথায়,
চরণে পতিত হইয়া বিনীত ও কাতর বচনে বলিলাম, ধর্মাবতার, এ ব্যক্তির বিষয়ে আমার কিছু বক্তব্য আছে।
অনুমতি হইলে সবিশেষ সমস্ত আপনকার গোচর করি। এই কথা শুনিবামাত্র তাহার কোপানল প্রজ্লিত হইয়া
উঠিল । তিনি রোষারক্ত নয়নে বলিলেন, আমি শপথ করিয়া বলিতেছি, যদি তুমি তাহাকে ছাড়িয়া দিয়া থাক,
এই দণ্ডে তোমার প্রাণদণ্ড হইবে । তখন আমি বলিলাম, আপনি ইচ্ছা করিলে, এই মুহূর্তে আমার ও তাহার
প্রাণদণ্ড করিতে পারেন তাহার সন্দেহ কি। কিন্তু, আমি যে নিবেদন করিতে ইচ্ছা করিতেছি, কৃপা করিয়া
তাহা শুনিলে, আমি চরিতার্থ হই।

এই কথা শুনিয়া খলিফা উদ্ধত বচনে বলিলেন, কী বলিতে চাও, বল। তখন সে ব্যক্তি ডেমাস্কাস
নগরে কীরূপে আশ্রয়দান ও প্রাণরক্ষা করিয়াছিলেন এবং এক্ষণে তাহাকে ছাড়িয়া দিতে চাহিলে, আমি
অবধারিত বিপদে পড়িব, এ জন্য তাহাতে কোনোমতে সম্মত হইলেন না; এই দুই বিষয়ে সবিশেষ
নির্দেশ করিয়া বলিলাম, ধর্মাবতার, যে ব্যক্তির এরূপ প্রকৃতি ও এরূপ মতি, অর্থাৎ যে ব্যক্তি এমন
দয়াশীল, পরোপকারী, ন্যায়পরায়ণ ও সদ্বিবেচক তিনি কখনই দুরাচার নহেন। নীচপ্রকৃতি পরহিংসুক
দুরাত্ারা, ঈর্যাবশত অমূলক দোষারোপ করিয়া তাহার সর্বনাশ করিতে উদ্যত হইয়াছে; নতুবা যাহাতে
প্রাণদণ্ড হইতে পারে, তিনি এরূপ কোনো দোষে দুষিত হইতে পারেন, আমার এরূপ বোধ ও বিশ্বাস
হয় না। এ ক্ষেত্রে আপনার যেরূপ অভিরুচি হয় করুন।

খলিফা মহামতি ও অতি উন্নতচিত্ত পুরুষ ছিলেন। তিনি এই সকল কথা কর্ণগোচর করিয়া কিয়ৎক্ষণ
মৌনাবলম্বন করিয়া রহিলেন; অনন্তর প্রসন্ন বদনে বলিলেন, সে ব্যক্তি যে এরূপ দয়াশীল ও ন্যায়পরায়ণ,ইহা
অবগত হইয়া আমি অতিশয় আহ্রাদিত হইলাম । তিনি প্রাণদণ্ড হইতে অব্যাহতি পাইলেন। বলিতে
গেলে, তোমা হইতেই তাহার প্রাণরক্ষা হইল । এক্ষণে তাহাকে অবিলম্বে এই সংবাদ দাও, ও আমার
নিকটে লইয়া আইস।

এই কথা শুনিয়া আন্রাদের সাগরে মগ্ন হইয়া আমি সত্র গৃহে প্রত্যাগমনপূর্বক তাহাকে খলিফার
বলিলেন, তুমি যে এরূপ প্রকৃতির লোক, তাহা আমি পূর্বে অবগত ছিলাম না। দুষ্টমতি দুরাচারদিগের
বাক্য বিশ্বাস করিয়া অকারণে তোমার প্রাণদণ্ড করিতে উদ্যত হইয়াছিলাম | এক্ষণে, ইহার নিকটে
তোমার প্রকৃত পরিচয় পাইয়া, সাতিশয় গ্রীতিপ্রাপ্ত হইয়াছি। আমি অনুমতি দিতেছি, তুমি আপন
দশ উদ্ট্র উপহার দিলেন এবং ডেমাস্কাসের রাজপ্রতিনিধির নামে এক অনুরোধপত্র ও পাথেয়স্বরূপ
বহুসংখ্যক অর্থ দিয়া তাহাকে বিদায় করিলেন ।

বা সাহচর্ষে। নিষ্কৃতি- মুক্তি। কোপানল- কোপ ও অনল মিলে কোপানল; ক্রোধ বা রাগের আগুন। এখানে
যাওয়া অর্থে ব্যবহার করা হয়েছে। প্রতীতি- বিশ্বাস; ধারণা । পরিচ্ছদ- পোশাক। গ্রীতিপ্রফুল্পলোচনে- শব্দটিতে
মূলত তিনটি শব্দ যুক্ত করা হয়েছে; প্রীতি, প্রফুল্ল ও লোচন-বন্ধুত্বের অনুভূতিতে আনন্দিত চোখে ।
লোচন অর্থ চোখ । মৌনাবলম্বন- মৌন ও অবলম্বন মিলে মৌনাবলম্বন; অর্থাৎ নীরবতা পালন।
অব্যাহতি- মুক্তি, ছাড়া পাওয়া । অবধারিত- নিশ্চিত। প্রত্যাগমন-ফিরে আসা। শব্দটি গঠিত দুটি
শব্দ মিলে: প্রতি ও আগমন । রোষারক্ত নয়নে- ক্রোধে লাল চোখে । অবলোকনমাত্র- দেখামাত্র।
সম্ভীষণ- সম্বোধন । উৎ্কট- অত্যন্ত প্রবল, তীব্র। অবরুদ্ধ- বন্দি। নিরীক্ষণ- মনোযোগ দিয়ে দেখা ।
খলিফা- প্রতিনিধি। হজরত মুহম্মদ (স.)-এর পরে মুসলিম রাষ্ট্রের সর্বপ্রধান শাসনকর্তাকে “খলিফা” বলা
হতো। তিনি একাধারে রাজ্যের প্রধান শাসক ও ধর্মনেতা ছিলেন।

ডেমাস্কাস- দামেস্ক । এশিয়ার একটি প্রাচীন শহর। হজরত ইব্রাহিমের (আ.) যুগের পূর্বে এখানে
মামুন- আল মামুন নামেই সমধিক পরিচিত । তার পূর্ণ নাম আবুল আব্বাস আবদুল্লাহ আল মামুন
(৭৮৬-৮৩৩ খিষ্টাব্দ)। তিনি ছিলেন সপ্তম আব্বাসীয় খলিফা এবং খলিফা হারুনর রশীদের দ্বিতীয় পুত্র ।
শ্রেষ্ঠ নগরীতে পরিণত হয়। টাইগ্রিস নদীর উভয় তীরে এবং ফুরাত বা ইউফ্রেটিস নদীর পঁচিশ
মাইল উত্তরে অবস্থিত। আব্বাসীয় খলিফা মনসুর ৭৬৩ খিষ্টাব্দে নগরটি প্রতিষ্ঠা করেন।

