### 📝 পাঠ-পরিচিতি : 'প্রত্যুপকার' রচনাটি আখ্যানমঞ্রী দ্বিতীয় ভাগ থেকে সংকলন করা হয়েছে।
ঈশ্বরচন্দ্র বিদ্যাসাগরের আখ্যানমঞ্জরী রচিত হয় ১৮৬৮ খিষ্টাব্দে | বিশ্বের নানা দেশের ইতিহাস
প্রসিদ্ধ ব্যক্তিগণের জীবনের গৌরবদীপ্ত ঘটনাই এ গ্রন্থের বিভিন্ন রচনার উপজীব্য । পপ্রত্যুপকার'
আলী আব্বাস নামক এক ব্যক্তির প্রতি-উপকারের কাহিনি । খলিফা মামুনের সময়ে দামেক্ষের
জনৈক শাসনকর্তা পদচ্যুত হন। নতুন শাসনকর্তা মামুনের একজন প্রিয়পাত্র ছিলেন আলী ইবনে আব্বাস।
আব্বাসের আশ্রয়দাতা এ সন্তান্ত ব্যক্তিটি খলিফা মামুনের সৈন্যদল কর্তৃক বন্দি হন এবং খলিফার
নির্দেশে আলী ইবনে আব্বাসের গৃহে তাকে অন্তরীণ করে রাখার ব্যবস্থা করা হয়। আলী ইবনে আব্বাস
এবং খলিফার কাছে তার মুক্তির জন্য সুপারিশ করেন। বন্তত এ রচনায় দুজন মহৎ ব্যক্তির কাহিনি
বর্ণিত হয়েছে, তাদের একজন নিঃস্বার্থ উপকারী, অন্যজন সকৃতজ্ঞ প্রত্যুপকারী। খলিফার মহত্ও
এ রচনায় প্রকাশিত হয়েছে।

কর্ম-অনুশীলন
১. কোনো ব্যক্তি তার উপকারীর উপকার করেছেন এমন কোনো ঘটনা তোমার জানা থাকলে তা লেখো ।
২. উপকারীর উপকার না করে অপকার করেছে; এরকম একটি ঘটনার বিবরণ দাও ।



### 🎯 নমুনা প্রশ্ন: বহুনির্বাচনি প্রশ্ন (MCQ)

১। খলিফা মামুন কততম আব্বাসীয় খলিফা ছিলেন?
ক. পঞ্চম   খ. ষষ্ঠ
গ. সপ্তম   ঘ. অষ্টম

২। “আমি এত নীচাশয় ও স্বার্থপর নহি যে, কিছুকাল পূর্বে যে প্রাণের রক্ষা করিয়াছি, আপন প্রাণরক্ষার্থে এক্ষণে সেই প্রাণের বিনাশের কারণ হইব ।”— বাক্যে প্রকাশ পেয়েছে:
ক. বীরত্ব   খ. ঔদার্য
গ. প্রত্যুপকার   ঘ. উদাসীনতা

নিচের উদ্দীপকটি পড়ে ৩ ও ৪ নং প্রশ্নের উত্তর দাও।

হাতেমের দানশীলতা ও পরোপকারিতার রোমাঞ্চকর কাহিনি শুনে রাজা মুগ্ধ এবং বিস্মিত হলেন। হাতেমের প্রতি ভক্তিতে রাজার হৃদয় পরিপূর্ণ হলো । বহুদিনের বৈরিভাব ভুলে তার কণ্ঠে ধ্বনিত হলো—
৩। উদ্দীপকের রাজা চরিত্রে প্রত্যুপকার গল্পের খলিফা মামুন চরিত্রের কোন বৈশিষ্ট্য প্রকাশ পেয়েছে?
ক. দানশীলতা   খ. মহানুভবতা
গ. ঔচিত্যবোধ   ঘ. প্রজাপ্রীতি

৪। উদ্দীপকের হাতেম ও প্রত্যুপকার গল্পের “ডেমাস্কাস অধিবাসী” অভিন্ন চেতনার ধারক কোন বিবেচনায়—
i. দানশীলতা
ii. প্রত্যুপকার
নিচের কোনটি ঠিক?

