# ২য় অধ্যায়: ফুলের বিবাহ (বঙ্কিমচন্দ্র চট্টোপাধ্যায়)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: বঙ্কিমচন্দ্র চট্টোপাধ্যায়*

---

### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি: বঙ্কিমচন্দ্র চট্টোপাধ্যায় ২৬শে জুন, ১৮৩৮ খিষ্টাব্দে পশ্চিমবঙ্গের চব্বিশ পরগনা জেলার
অন্তর্গত কঁঠালপাড়া গ্রামে জনুগ্রহণ করেন। তিনি ১৮৫৮ সালে কলকাতা বিশ্ববিদ্যালয় থেকে বিএ
পরীক্ষায় উত্তীর্ণ হন এবং সে বছরই ডেপুটি ম্যাজিস্ট্রেট ও ডেপুটি কালেক্টুর পদে নিযুক্ত হন। তাঁর
অসামান্য কৃতিত্ব প্রকাশ পেয়েছে পাশ্চাত্য ভাবাদর্শে বাংলা উপন্যাস রচনার পথিকৃৎ হিসেবে । ১৮৬৫
খিষ্টান্দে প্রকাশিত তাঁর প্রথম বাংলা উপন্যাস দুর্গেশনন্দিনী বাংলা কথাসাহিত্যে এক নবদিগন্ত উন্মোচন
করে । তাঁর অন্যান্য উপন্যাস হলো: কগালকুন্ডলা , মুণালিনী , বিষবৃক্ষ, ইন্দিরা , যুগলাঙ্গুরীয়, রাধারানী ,
প্রবন্ধ-সাহিত্যেও বঙ্কিমচন্দ্র কৃতিত্ব দেখিয়েছেন। কমলাকান্তের দণ্ডর, লোকরহস্য, কৃষ্ণচরিত্র ইত্যাদি
তাঁর উল্লেখযোগ্য প্রবন্ধপ্রন্থ। বঙ্কিমচন্দ্র চট্টোপাধ্যায় ১৮৯৪ খিষ্টাব্দের ৮ই এপ্রিল মৃত্যুবরণ করেন |

---

## 📖 মূল পাঠ (গদ্য)

ফুলের বিবাহ

বঙ্কিমচন্দ্র চট্টোপাধ্যায়



বৈশাখ মাস বিবাহের মাস। আমি ১লা বৈশাখে নসী বাবুর ফুলবাগানে বসিয়া একটি বিবাহ
দেখিলাম ভবিষ্যৎ বরকন্যাদিগের শিক্ষার্থ লিখিয়া রাখিতেছি।

পিতা বড়োলোক নহে, ক্ষুদ্র বৃক্ষ, তাহাতে আবার অনেকগুলি কন্যাভারগ্রস্ত। সম্বন্ধের অনেক কথা
হইতেছিল, কিন্তু কোনটা স্থির হয় নাই। উদ্যানের রাজা স্থলপদ্স নির্দোষ পাত্র বটে, কিন্তু ঘর বড়ো উচু,
স্থলপদ্ম অত দূর নামিল না। জবা এ বিবাহে অসম্মত ছিল না, কিন্তু জবা বড়ো রাগী, কন্যাকর্তা
পিছাইলেন। গন্ধরাজ পাত্র ভালো, কিন্তু বড়ো দেমাগ, প্রায় তাহার বর পাওয়া যায় না। এইরূপ

গুণ্‌ ! গুণ্‌ ! গুণ্‌ মেয়ে আছে?

গুণ্‌ গুণাগুণৃ! মেয়ে দেখিব |,

বৃক্ষ, শাখা নত করিয়া মুদিতনয়না অবগ্ুষ্ঠনবতী কন্যা দেখাইলেন।

ভ্রমর একবার বৃক্ষকে প্রদক্ষিণ করিয়া আসিয়া বলিলেন, গুণ! গুণৃ! গুণ ! গুণ দেখিতে চাই। ঘোমটা খোল ।”

লজ্জাশীলা কন্যা কিছুতেই ঘোমটা খুলে না। বৃক্ষ বলিলেন, 'আমার মেয়েগুলি বড়ো লাজুক । তুমি
একটু অপেক্ষা কর, আমি মুখ দেখাইতেছি।”



মন্নিকার সন্ধ্যাঠাকুরাণী-দিদি আসিয়া তাহাকে কত বুঝাইতে লাগিল-_ বলিল, “দিদি, একবার ঘোমটা
খোল- নইলে,বর আসিবে না- লক্ষ্মী আমার, চাদ আমার, সোনা আমার, ইত্যাদি ।' কলিকা কতবার
ঘাড় নাড়িল, কতবার রাগ করিয়া মুখ ঘুরাইল, কতবার বলিল, 'ঠান্দিদি, তুই যা!” কিন্ত শেষে
সন্ধ্যার ফ্রিগ্ধ স্বভাবে মুগ্ধ হইয়া মুখ খুলিল। তখন ঘটক মহাশয় ভৌ করিয়া রাজবাড়ি হইতে নামিয়া
আসিয়া ঘটকালিতে মন দিলেন। কন্যার পরিমলে মুগ্ধ হইয়া বলিলেন, “গুণ্‌ গুণ্‌ গুণ্‌ গুণ গুণাগুণ্‌ !
কন্যা গুণবতী বটে । ঘরে মধু কত?

আপনার অনেক গুণ-- ঘটকালিটা?'

কন্যাকর্তা শাখা নাড়িয়া সায় দিল, “তাও হবে ।'

ভ্রমর- বিলি ঘটকালির কিছু আগাম দিলে হয় না নগদ দান বড়ো গুণ-গুণ্‌ গুণ্‌ গুণৃ।'

দ্র বৃক্ষটি তখন বিরক্ত হইয়া, সকল শাখা নাড়িয়া বলিল, 'আগে বরের কথা বল- বর কে?
ভ্রমর_ “বর অতি সুপাত্র।_ তার অনেক গুণ-ণ- ণ্‌।'

এ সকল কথোপকথন মনুষ্যে শুনিতে পায় না, আমি কেবল দিব্য কর্ণ পাইয়াই এ সকল শুনিতেছিলাম।
আমি শুনিতে লাগিলাম, কুলাচার্য মহাশয়, পাখা ঝাড়িয়া, ছয় পা ছড়াইয়া গোলাবের মহিমা কীর্তন
করিতেছিলেন। বলিতেছিলেন যে, গোলাপ বংশ বড়ো কুলীন; কেন না, ইহারা “ফুলে মেল। যদি
বল, সকল ফুলই ফুলে, তথাপি গোলাপের গৌরব অধিক; কেন না, ইহারা সাক্ষাৎ বাঞ্কামালির সন্তান;
তাহার স্বহস্তরোপিত। যদি বল, এ ফুলে কাটা আছে, কোন্‌ কুলে বা কোন্‌ ফুলে নাই?

যাহা হউক, ঘটকরাজ কোনরূপে সম্বন্ধ স্থির করিয়া, বৌ করিয়া উড়িয়া গিয়া, গোলাব বাবুর

গোধুলিলগ্ন উপস্থিত, গোলাব বিবাহে যাত্রার উদ্যোগ করিতে লাগিলেন । উচ্চিজড়া নহবৎ বাজাইতে
না। খদ্যোতেরা ঝাড় ধরিল; আকাশে তারাবাজি হইতে লাগিল । কোকিল আগে আগে ফুকরাইতে
পারিলেন না, কিন্তু জবাগোষ্ঠী_ শ্বেত জবা, রক্ত জবা, জরদ জবা প্রভৃতি সবংশে আসিয়াছিল।

নীতবর হইবে বলিয়া, সাজিয়া আসিয়া দুলিতে লাগিল। গরদের জোড় পরিয়া টাপা আসিয়া
দেশ মাতাইতে লাগিল। অশোক নেশায় লাল হইয়া আসিয়া উপস্থিত; সঙ্গে একপাল পিঁপড়া মোসায়েব
হইয়া আসিয়াছে; তাহাদের গুণের সঙ্গে সম্বন্ধ নাই, কিন্তু দাতের জ্বালা বড়ো- কোন বিবাহে না এরূপ
বরযাত্রী জোটে, আর কোন বিবাহে না তাহারা হুল ফুটাইয়া বিবাদ বাধায়? কুরুবক কুটজ প্রভৃতি
যাতায়াত করেন এবং কিছু কিছু মধু পাইয়া থাকেন।

আমারও নিমন্ত্রণ ছিল, আমিও গেলাম । দেখি, বরপক্ষের বড়ো বিপদ । বাতাস বাহকের বায়না
আছেন। মল্লিকাদিগের কুল যায় দেখিয়া, আমিই বাহকের কার্ষ স্বীকার করিলাম । বর, বরযাত্রী
সকলকে তুলিয়া লইয়া মন্নিকাপুরে গেলাম ।

সেখানে দেখিলাম, কন্যাকুল, সকল ভগিনী, আত্রাদে ঘোমটা খুলিয়া মুখ ফুটাইয়া, পরিমল ছুটাইয়া,

সুখের হাসি হাসিতেছে। দেখিলাম, পাতায় পাতায় জড়াজড়ি, গন্ধের ভাগ্ারে ছড়াছড়ি পড়িয়া গিয়াছে
_রূপের ভারে সকলে ভাঙিয়া পড়িতেছে। যুখী, মালতী, বকুল, রজনীগন্ধা প্রভৃতি এয়োগণ স্ত্রী-আচার
করিয়া বরণ করিল । দেখিলাম, পুরোহিত উপস্থিত; নসী বাবুর নবমবর্ষীয়া কন্যা (জীবন্ত কুসুমরূপিণী)
দুইজনকে এক সুতায় গাথিয়া গাটছড়া বাধিয়া দিলেন ।

তখন বরকে বাসর-ঘরে লইয়া গেল । কত যে রসময়ী মধুময়ী সুন্দরী সেখানে বরকে ঘিরিয়া বসিল,
তাহা কি বলিব। প্রাচীনা ঠাকুরাণীদিদি টগর সাদা প্রাণে বাধা রসিকতা করিতে করিতে শুকাইয়া
উঠিলেন। রঙ্গণের রাঙ্গামুখে হাসি ধরে না। জুই,কন্যের সই, কন্যের কাছে গিয়া শুইল; রজনীগন্ধাকে
বর তাড়কা রাক্ষসী বলিয়া কতো তামাসা করিল; বকুল একে বালিকা, তাতে যত গুণ, তত রূপ নহে;
এককোণে গিয়া চুপ করিয়া বসিয়া রহিল; আর ঝুমৃকা ফুল বড়ো মানুষের গৃহিণীর মতো মোটা নীল শাড়ি
ছড়াইয়া জমকাইয়া বসিল। তখন-_

“কমলকাকা-ওঠ বাড়ি যাই- রাত হয়েছে, ও কি, ঢুলে পড়বে যে? কুসুমলতা এই কথা বলিয়া আমার
গা ঠেলিতেছিল; - চমক হইলে, দেখিলাম কিছুই নাই। সেই পুস্পবাসর কোথায় মিশিল? - মনে
করিলাম, সংসার অনিত্যই বটে_ এই আছে এই নাই। সে রম্য বাসর কোথায় গেল,_ সেই
হাস্যমুখী শুত্রস্মিতসুধাময়ী পুষ্পসুন্দরীসকল কোথায় গেল? যেখানে সব যাইবে, সেইখানে- স্মৃতির
দর্পণতলে, ভূতসাগরগর্ভে। যেখানে রাজা প্রজা, পর্বত সমুদ্র, গ্রহ নক্ষত্রাদি গিয়াছে বা যাইবে,
সেইখানে _ ধ্বংসপুরে! এই বিবাহের ন্যায় সব শুন্যে মিশাইবে, সব বাতাসে গলিয়া যাইবে ।

কুসুম বলিল, “ওঠ না-কি কচ্চো?
আমি বলিলাম, “দূর পাগলি, আমি বিয়ে দিচ্ছিলাম ।'

“ওঃ পোড়া কপাল, ফুলের? আমি বলি কি! আমিও যে এই ফুলের বিয়ে দিয়েছি ।”
কই?
“এই যে মালা গেথেছি।' দেখিলাম, সেই মালায় আমার বর কন্যা রহিয়াছে।

---

### 📚 শব্দার্থ ও টীকা : কন্যাভারপ্রস্ত - বিবাহযোগ্যা কন্যা বিয়ে দেওয়ার দায়িত্ব বহনকারী অর্থে।
সম্বন্ধের -বিয়ের। কন্যাকর্তা - কন্যার অভিভাবক। পত্রাসন - পাতার ওপর আসন। অবগুগ্ঠনবতী
_ ঘোমটা দেওয়া নারী । ইয়ারকি _ রসিকতা; ফাজলামি সন্ধ্যাঠাকুরাণী দিদি _ এখানে সন্ধ্যাকালকে
দিদি বলে সম্বোধন করা হয়েছে। পরিমল _ সুগন্ধ । গন্ধোপাধ্যায় - গন্ধের রাজা বোঝাতে।
কুলাচার্য - কুলের আচার্য বা বংশের প্রধান পুরোহিত। বাঞ্কামালি - যে মালি ইচ্ছামতো ফুল
ফোটাতে পারে। খদ্যোত - জোনাকি পোকা। এয়োগণ - সধবা নারীরা। কমলকাকা - কমলাকান্তকে
কাকা বলে সম্বোধন করা হয়েছে।

---

### 📝 পাঠ পরিচিতি : বঙ্কিমচন্দ্র চট্টোপাধ্যায়ের লঘুরচনা কমলাকান্তের দপ্তর গ্রন্থের নবম সংখ্যক লেখা
“ফুলের বিবাহ" ৷ এই রচনায় হাস্যরসের মাধ্যমে বিভিন্ন ফুলের নাম, সে ফুলগুলোর গন্ধের তারতম্য,
বর্ণের রকমফের অত্যন্ত সংবেদনশীলতার সঙ্গে তুলে ধরেছেন বঙ্কিমচন্দ্র । কখন কোন ফুল ফোটে সে
পর্যবেক্ষণও এই রচনায় পাওয়া যায়। বিয়ে-অনুষ্ঠান বাড়ির শিশু-কিশোর ও প্রতিবেশীদের মধ্যে অতীব
আনন্দ নিয়ে আসে । এই অনুষ্ঠানে বর-কনে কেন্দ্রে থাকলেও বর-কনের মাতা-পিতা, কনের পড়শি
থাকেন এমন নানা ব্যক্তির পরিবর্তে বিভিন্ন ফুলের উল্লেখ করে অসাধারণ দক্ষতায় বন্কিমচন্দ্
বাঙালির গাহৃস্থ্য একটি অনুষ্ঠানকে আরও আনন্দদায়ক করে এখানে উপস্থাপন করেছেন । এখানে
গদ্যটি কৌতুহলী ও পর্যবেক্ষণশীল দৃষ্টিভঙ্গি তৈরি করতে সহায়ক।

কর্ম-অনুশীলন
১. পাঠটিতে যেসব ফুলের কথা বলা হয়েছে সেগুলোর নাম ও গন্ধের পরিচয় দিয়ে একটি ছক তৈরি করো ।
২. ফুলের বহুবিধ ব্যবহার লিপিবদ্ধ করে শ্রেণি শিক্ষককে দেখাও ।

