# ৩য় অধ্যায়: শুভা (রবীন্দ্রনাথ ঠাকুর)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: রবীন্দ্রনাথ ঠাকুর*

---

## 📖 মূল পাঠ (গদ্য)

সুভা
রবীন্দ্রনাথ ঠাকুর

[লেখক -পরিচিতি : রবীন্দ্রনাথ ঠাকুর ২৫শে বৈশাখ, ১২৬৮ বঙ্গাব্দে (৭ই মে, ১৮৬১ খিষ্টাব্দ) কলকাতার
জোড়াসাকোর ঠাকুর পরিবারে জনুগ্রহণ করেন। তার পিতা মহর্ষি দেবেন্দ্রনাথ ঠাকুর এবং পিতামহ
প্রিন্স দ্বাকানাথ ঠাকুর । বাল্যকালেই তার কবিপ্রতিভার উন্মেষ ঘটে । মাত্র পনেরো বছর বয়সে তার বনফুল
কাব্য প্রকাশিত হয়। ১৯১৩ খিষ্টাব্দে রবীন্দ্রনাথ ইংরেজি ০7127/071- 5০7৫ ০777/1৫5 সংকলনের জন্য
এশীয়দের মধ্যে সাহিত্যে প্রথম নোবেল পুরস্কার লাভ করেন। বন্তত তার একক সাধনায় বাংলা ভাষা ও
সাহিত্য সকল শাখায় দ্রুত উন্নতি লাভ করে এবং বিশ্বদরবারে গৌরবের আসনে প্রতিষ্ঠিত হয়। তিনি একাধারে
প্রবন্ধ, গান ইত্যাদি সাহিত্যের সকল শাখাই তার অবদানে সমৃদ্ধ হয়েছে। তার অজস্র রচনার মধ্যে মানসী,
কবিতা, বিসজর্ন, ডাকঘর, রক্তকরবী, গল্পওচ্ছ, বিচিত্র প্রবন্ধ ইত্যাদি বিশেষভাবে উল্লেখযোগ্য ৷ ২২শে শ্রাবণ,
১৩৪৮ বঙ্গাব্দে ৭ই আগস্ট, ১৯৪১ খরিষ্টাব্দ) কলকাতায় বিশ্বকবি রবীন্দ্রনাথ ঠাকুর শেষ নিঃশ্বাস ত্যাগ করেন। ]

মেয়েটির নাম যখন সুভাষিণী রাখা হইয়াছিল তখন কে জানিত সে বোবা হইবে । তাহার দুটি বড়ো
বোনকে সুকেশিনী ও সুহাসিনী নাম দেওয়া হইয়াছিল, তাই মিলের অনুরোধে তাহার বাপ ছোটো
মেয়েটির নাম সুভাষিণী রাখে । এখন সকলে তাহাকে সংক্ষেপে সুভা বলে।

দস্তরমতো অনুসন্ধান ও অর্থব্যয়ে বড়ো দুটি মেয়ের বিবাহ হইয়া গেছে, এখন ছোটোটি পিতামাতার

যে কথা কয় না সে যে অনুভব করে ইহা সকলের মনে হয় না, এইজন্য তাহার সাক্ষাতেই সকলে
তাহার ভবিষ্যৎ সম্বন্ধে দুশ্চিন্তা প্রকাশ করিত। সে যে বিধাতার অভিশাপস্বরূপে তাহার পিতৃগৃহে
আসিয়া জন্মগ্রহণ করিয়াছে এ কথা সে শিশুকাল হইতে বুঝিয়া লইয়াছিল। তাহার ফল এই
হইয়াছিল, সাধারণের দৃষ্টিপথ হইতে সে আপনাকে গোপন করিয়া রাখিতে সর্বদাই চেষ্টা করিত।
মনে করিত, আমাকে সবাই ভুলিলে বাচি। কিন্তু, বেদনা কি কেহ কখনো ভোলে? পিতামাতার মনে
সে সর্বদাই জাগরূক ছিল।

বিশেষত, তাহার মা তাহাকে নিজের একটা ক্রটিস্বরূপ দেখিতেন; কেননা, মাতা পুত্র অপেক্ষা কন্যাকে
নিজের অংশরূপে দেখেন_ কন্যার কোনো অসম্পূর্ণতা দেখিলে সেটা যেন বিশেষরূপে নিজের লজ্জার
কারণ বলিয়া মনে করেন। বরঞ্চ, কন্যার পিতা বাণীকণ্ঠ সুভাকে তাহার অন্য মেয়েদের
তাহার প্রতি বড়ো বিরক্ত ছিলেন। সুভার কথা ছিল না, কিন্তু তাহার সুদীর্ঘপল্লববিশিষ্ট বড়ো বড়ো
দুটি কালো চোখ ছিল-এবং তাহার ওষ্ঠাধর ভাবের আভাসমাত্রে কচি কিশলয়ের মতো কীপিয়া উঠিত ।

কথায় আমরা যেভাব প্রকাশ করি সেটা আমাদিগকে অনেকটা নিজের চেষ্টায় গড়িয়া লইতে হয়,
কতকটা তর্জমা করার মতো; সকল সময়ে ঠিক হয় না, ক্ষমতার অভাবে অনেক সময়ে ভুলও
হয়। কিন্তু কালো চোখকে কিছু তর্জমা করিতে হয় না- মন আপনি তাহার উপরে ছায়া ফেলে;
ভাব আপনি তাহার উপরে কখনো প্রসারিত কখনো মুদিত হয়, কখনো উজ্জ্বলভাবে জুলিয়া উঠে,
কখনো ম্লানভাবে নিবিয়া আসে, কখনো অস্তমান চন্দ্রের মতো অনিমেষভাবে চাহিয়া থাকে, কখনো
দ্রুত চঞ্চল বিদ্যুতের মতো দিগৃবিদিকে ঠিকরিয়া উঠে । মুখের ভাব বৈ আজন্মকাল যাহার অন্য
ভাষা নাই তাহার চোখের ভাষা অসীম উদার এবং অতলস্পর্শ গভীর- অনেকটা স্বচ্ছ আকাশের মতো,
উদয়ান্ত এবং ছায়ালোকের নিস্তব্ধ রঙ্গভূমি। এই বাক্যহীন মনুষ্যের মধ্যে বৃহৎ প্রকৃতির মতো
একটা বিজন মহত্ব আছে। এইজন্য সাধারণ বালকবালিকারা তাহাকে একপ্রকার ভয় করিত, তাহার
সহিত খেলা করিত না । সে নির্জন দ্বিপ্রহরের মতো শব্দহীন এবং সঙ্গীহীন।

গ্রামের নাম চণ্তীপুর। নদীটি বাংলাদেশের একটি ছোটো নদী, গৃহস্থঘরের মেয়েটির মতো, বহুদূর
ধারের গ্রামের সকলেরই সঙ্গে তাহার যেন একটা-না-একটা সম্পর্ক আছে। দুই ধারে লোকালয় এবং
তরুচ্ছায়াঘন উচ্চ তটঃ নিয়তল দিয়া গ্রামলক্ষ্মী স্রোতস্বিনী আত্মবিস্মৃত দ্রুত পদক্ষেপে প্রফুন্ন হদয়ে
আপনার অসংখ্য কল্যাণকার্ষে চলিয়াছে।

বাণীকপ্ঠের ঘর নদীর একেবারে উপরেই । তাহার বাখারির বেড়া, আটচালা, গোয়ালঘর, টেকিশালা,
খড়ের স্তূপ, তেতুলতলা, আম কীঠাল এবং কলার বাগান নৌকাবাহী-মাত্রেরই দৃষ্টি আকর্ষণ করে।
এই গাহস্থ্য সচ্ছলতার মধ্যে বোবা মেয়েটি কাহারও নজরে পড়ে কি না জানি না, কিন্তু কাজকর্মে
যখনই অবসর পায় তখনই সে এই নদীতীরে আসিয়া বসে ।

প্রকৃতি যেন তাহার ভাষার অভাব পূরণ করিয়া দেয়। যেন তাহার হইয়া কথা কয়। নদীর কলধ্বনি,
আন্দোলন-কম্পনের সহিত এক হইয়া সমুদ্রের তরঙ্গরাশির ন্যায় বালিকার চিরনিস্তন্ধ হৃদয়-
উপকূলের নিকটে আসিয়া ভাঙিয়া ভায়া পড়ে। প্রকৃতির এই বিবিধ শব্দ এবং বিচিত্র গতি, ইহাও
বোবার ভাষা - বড়ো বড়ো চক্ষুপল্পববিশিষ্ট সুভার যেভাষা তাহারই একটা বিশ্বব্যাপী বিস্তার;
ঝিল্লিরবপূর্ণ তৃণভূমি হইতে শব্দাতীত নক্ষত্রলোক পর্যন্ত কেবল ইঙ্গিত, ভঙ্গি, সংগীত, ক্রন্দন এবং
দীর্ঘনিশ্বাস।

এবং মধ্যাক্নে যখন মাঝিরা, জেলেরা খাইতে যাইত, গৃহস্থেরা ঘুমাইত, পাখিরা ডাকিত না, খেয়া-নৌকা
বন্ধ থাকিত, সজন জগৎ সমস্ত কাজকর্মের মাঝখানে সহসা থামিয়া গিয়া ভয়ানক বিজনমূর্তি ধারণ
করিত তখন রুদ্র মহাকাশের তলে কেবল একটি বোবা প্রকৃতি এবং একটি বোবা মেয়ে মুখামুখি
চুপ করিয়া বসিয়া থাকিত-একজন সুবিস্তীর্ণ রৌদ্রে, আর-একজন ক্ষুদ্র তরুচ্ছায়ায় ।



সুভার যে গুটিকতক অন্তরঙ্গ বন্ধুর দল ছিল না তাহা নহে। গোয়ালের দুটি গাভী, তাহাদের নাম
সর্বশী ও পাঙ্গুলি। সে নাম বালিকার মুখে তাহারা কখনো শুনে নাই, কিন্তু তাহার পদশব্দ তাহারা
চিনিত- তাহার কথাহীন একটা করুণ সুর ছিল, তাহার মর্ম তাহারা ভাষার অপেক্ষা সহজে বুঝিত।
সুভা কখন তাহাদের আদর করিতেছে, কখন ভ€সনা করিতেছে, কখন মিনতি করিতেছে, তাহা

গণ্তদেশ ঘর্ষণ করিত এবং গাঙ্গুলি স্রিথধদৃষ্টিতে তাহার প্রতি নিরীক্ষণ করিয়া তাহার গা চাটিত।
বালিকা দিনের মধ্যে নিয়মিত তিনবার করিয়া গোয়ালঘরে যাইত, তাহা ছাড়া অনিয়মিত আগমনও
ছিল; গৃহে যেদিন কোনো কঠিন কথা শুনিত সেদিন সে অসময়ে তাহার এই মূক বন্ধু দুটির কাছে
আসিত- তাহার সহিষ্কুতাপরিপূর্ণ বিষাদশান্ত দৃষ্টিপাত হইতে তাহারা কী একটা অন্ধ অনুমানশক্তির
দ্বারা বালিকার মর্মবেদনা যেন বুঝিতে পারিত, এবং সুভার গা ঘেঁষিয়া আসিয়া অল্পে অল্পে তাহার
বাহুতে শিং ঘষিয়া ঘষিয়া তাহাকে নির্বাক ব্যাকুলতার সহিত সান্ত্বনা দিতে চেষ্টা করিত।

ইহারা ছাড়া ছাগল এবং বিড়ালশাবকও ছিল; কিন্ত তাহাদের সহিত সুভার এরূপ সমকক্ষভাবে মৈত্রী
ছিল না, তথাপি তাহারা যথেষ্ট আনুগত্য প্রকাশ করিত। বিড়ালশিশুটি দিনে এবং রাত্রে যখন-
তখন সুভার গরম কোলটি নিঃসংকোচে অধিকার করিয়া সুখনিদ্রার আয়োজন করিত এবং সুভা
তাহার গ্রীবা ও পৃষ্ঠে কোমল অঙ্গুলি বুলাইয়া দিলে যে তাহার নিদ্ৰাকর্ষণের বিশেষ সহায়তা হয়,
ইঙ্গিতে এরূপ অভিপ্রায়ও প্রকাশ করিত।

উন্নত শ্রেণির জীবের মধ্যে সুভার আরও একটি সঙ্গী জুটিয়াছিল। কিন্তু তাহার সহিত বালিকার ঠিক
কিরূপ সম্পর্ক ছিল তাহা নির্ণয় করা কঠিন, কারণ, সে ভাষাবিশিষ্ট জীব; সুতরাং উভয়ের মধ্যে
সমভাষা ছিল না।

গৌসাইদের ছোটো ছেলেটি- তাহার নাম প্রতাপ । লোকটি নিতান্ত অকর্মণ্য। সে যে কাজকর্ম করিয়া
সংসারের উন্নতি করিতে যত্বু করিবে, বহু চেষ্টার পর বাপ-মা সে আশা ত্যাগ করিয়াছেন । অকর্মণ্য
লোকের একটা সুবিধা এই যে, আত্মীয় লোকেরা তাহাদের উপর বিরক্ত হয় বটে, কিন্তু প্রায়
সম্পত্তি হইয়া দীড়ায়। শহরের যেমন এক-আধটা গৃহসম্পর্কহীন সরকারি বাগান থাকা আবশ্যক
অবসরে যেখানে একটা লোক কম পড়ে সেখানেই তাহাদিগকে হাতের কাছে পাওয়া যায়।

প্রতাপের প্রধান শখ-ছিপ ফেলিয়া মাছ ধরা। ইহাতে অনেক সময় সহজে কাটানো যায়। অপরাহে
নদীতীরে ইহাকে প্রায় এই কাজে নিযুক্ত দেখা যাইত এবং এই উপলক্ষে সুভার সহিত তাহার প্রায়
সাক্ষাৎ হইত । যে-কোনো কাজেই নিযুক্ত থাক, একটা সঙ্গী পাইলে প্রতাপ থাকে ভালো । মাছ
ধরার সময় বাক্যহীন সঙ্গীই সর্বাপেক্ষা শ্রেষ্ঠ-এইজন্য প্রতাপ সুভার মর্ধাদা বুঝিত। এইজন্য, সকলেই
সুভাকে সুভা বলিত, প্রতাপ আর-একটু অতিরিক্ত আদর সংযোগ করিয়া সুভাকে “সু' বলিয়া ডাকিত।

সভা তেতুলতলায় বসিয়া থাকিত এবং প্রতাপ অনতিদূরে ছিপ ফেলিয়া জলের দিকে চাহিয়া
থাকিত। প্রতাপের জন্য একটি করিয়া পান বরাদ্দ ছিল, সুভা তাহা নিজে সাজিয়া আনিত। এবং
বোধ করি অনেকক্ষণ বসিয়া বসিয়া চাহিয়া ইচ্ছা করিত, প্রতাপের কোনো-একটা বিশেষ সাহায্য
করিতে, একটা-কোনো কাজে লাগিতে, কোনোমতে জানাইয়া দিতে যে এই পৃথিবীতে সেও একজন
কম প্রয়োজনীয় লোক নহে। কিন্ত কিছুই করিবার ছিল না। তখন সে মনে মনে বিধাতার কাছে
অলৌকিক ক্ষমতা প্রার্থনা করিত- মন্ত্রবলে সহসা এমন একটা আশ্চর্য কাণ্ড ঘটাইতে ইচ্ছা করিত
যাহা দেখিয়া প্রতাপ আশ্চর্য হইয়া যাইত, বলিত, “তাই তো, আমাদের সুভির যে এত ক্ষমতা তাহা
তো জানিতাম না।”

মনে করো, সুভা যদি জলকুমারী হইত; আস্তে আস্তে জল হইতে উঠিয়া একটা সাপের মাথার মণি ঘাটে
রাখিয়া যাইত; প্রতাপ তাহার তুচ্ছ মাছধরা রাখিয়া সেই মানিক লইয়া জলে ডুব মারিত; এবং পাতালে
গিয়া দেখিত, রুপার অস্টালিকায় সোনার পালক্কে-কে বসিয়া?_ আমাদের বাণীকণ্ঠের ঘরের সেই বোবা
মেয়ে সু- আমাদের সু সেই মণিদীপ্ত গভীর নিস্তব্ধ পাতালপুরীর একমাত্র রাজকন্যা ৷ তাহা কি হইতে
পারিত না, তাহা কি এতই অসম্ভব । আসলে কিছুই অসম্ভব নয়, কিন্তু তবুও সু প্রজাশুন্য পাতালের
রাজবংশে না জন্নয়া বাণীকণ্ঠের ঘরে আসিয়া জন্নিয়াছে এবং গৌসাইদের ছেলে প্রতাপকে কিছুতেই
আশ্চর্য করিতে পারিতেছে না।

সুভার বয়স ক্রমেই বাড়িয়া উঠিতেছে। ক্রমে সে যেন আপনাকে আপনি অনুভব করিতে পারিতেছে।
যেন কোনো একটা পূর্ণিমাতিথিতে কোনো-একটা সমুদ্র হইতে একটা জোয়ারের পরোতে আসিয়া
তাহার অন্তরাত্ৰাকে এক নৃতন অনির্বচনীয় চেতনাশক্তিতে পরিপূর্ণ করিয়া তুলিতেছে। সে আপনাকে
আপনি দেখিতেছে,ভাবিতেছে, প্রশ্ন করিতেছে, এবং বুঝিতে পারিতেছে না।

গভীর পূর্ণিমারাত্রেসে এক-একদিন ধীরে শয়নগৃহের দ্বার খুলিয়া ভয়ে ভয়ে মুখ বাড়াইয়া বাহিরের
দিকে চাহিয়া দেখে পূর্ণিমাপ্রকৃতিও সুভার মতো একাকিনী সুপ্ত জগতের উপর জাগিয়া বসিয়া
যৌবনের রহস্যে পুলকে বিষাদে অসীম নির্জনতার একেবারে শেষ সীমা পর্যন্ত, এমন_ কি, তাহা
অতিক্রম করিয়াও ধমথম করিতেছে, একটি কথা কহিতে পারিতেছে না। এই নিস্তব্ধ ব্যাকুল

এ দিকে কন্যাভারপ্রস্ত পিতামাতা চিন্তিত হইয়া উঠিয়াছেন। লোকেও নিন্দা আরম্ভ করিয়াছে । এমন-কি,
এক-ঘরে করিবে এমন জনরবও শুনা যায়। বাণীকণ্ঠের সচ্ছল অবস্থা, দুই বেলাই মাছভাত খায়,
এজন্য তাহার শত্রু ছিল।

্ত্রীপুরুষে বিস্তর পরামর্শ হইল । কিছুদিনের মতো বাণী বিদেশে গেল ।


একেবারে ভরিয়া গেল। একটা অনির্দিষ্ট আশঙ্কা বশে সে কিছুদিন হইতে ক্রমাগত নির্বাক জন্তর
মতো তাহার বাপ-মায়ের সঙ্গে সঙ্গে ফিরিত- ডাগর চক্ষু মেলিয়া তাহাদের মুখের দিকে চাহিয়া
কী- একটা বুঝিতে চেষ্টা করিত, কিন্তু তাহারা কিছু বুঝাইয়া বলিতেন না।

ইতিমধ্যে একদিন অপরাহে ছিপ ফেলিয়া প্রতাপ হাসিয়া কহিল, “কী রে সু, তোর নাকি বর পাওয়া

গেছে, তুই বিয়ে করতে যাচ্ছিস? দেখিস আমাদের ভুলিস নে।” বলিয়া আবার মাছের দিকে মনোযোগ
করিল।

মর্মবিদ্ধ হরিণী ব্যাধের দিকে যেমন করিয়া তাকায়, নীরবে বলিতে থাকে আমি তোমার কাছে
কী দোষ করিয়াছিলাম", সুভা তেমনি করিয়া প্রতাপের দিকে চাহিল; সেদিন গাছের তলায় আর
বসিল না; বাণীকণ্ঠ নিদ্রা হইতে উঠিয়া শয়নগৃহে তামাক খাইতেছিলেন, সুভা তাহার পায়ের কাছে
বসিয়া তাহার মুখের দিকে চাহিয়া কীদিতে লাগিল । অবশেষে তাহাকে সান্তনা দিতে গিয়া বাণীকণ্ঠের
শুক্ক কপোলে অশ্রু গড়াইয়া পড়িল।

কাল কলিকাতায় যাইবার দিন স্থির হইয়াছে। সুভা গোয়ালঘরে তাহার বাল্য-সখীদের কাছে বিদায়
লইতে গেল, তাহাদিগকে স্বহস্তে খাওয়াইয়া, গলা ধরিয়া একবার দুই চোখে যত পারে কথা ভরিয়া
তাহাদের মুখের দিকে চাহিল- দুই নেত্রপল্লব হইতে টপ টপ করিয়া অশ্রুজল পড়তে লাগিল ।

চাহে, “তুমি আমাকে যাইতে দিয়ো না মা, আমার মতো দুটি বাহু বাড়াইয়া তুমিও আমাকে ধরিয়া
রাখো ।” এ [সংক্ষেপিত]

