### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন
দুই পুত্রসন্তানের পর কন্যাসন্তান পলাশ বাবুর পরিবারে আনন্দের বন্যা নিয়ে এল। নাম রাখা
হলো কল্যাণী”। সকলের চোখের মণি কল্যাণী বেড়ে ওঠার সঙ্গে সঙ্গে পলাশ বাবু বুঝতে
থাকে । কল্যাণীর বিয়ের কথাবার্তা চলছে। পলাশবাবু কল্যাণীর অবস্থা বরপক্ষকে খুলে বললেন।
সব শুনে বরের বাবা সুবোধ বাবু বললেন, “পলাশ বাবু কল্যাণীর মতো আমার ছেলেও তো হতে
পারত, কাজেই কল্যাণীমাকে ঘরে নিতে আমাদের কোনো আপত্তি নেই ।
ক. সুভার গ্রামের নাম কী?
খ. “পিতা-মাতার নীরব হৃদয়ভার' _ কথাটি দ্বারা লেখক কী বোঝাতে চেয়েছেন?
গ. উদ্দীপকের প্রথম অংশের বক্তব্যে কল্যাণী ও সুভার যে বিশেষ দিকটির সঙ্গতি দেখানো হয়েছে,

তা ব্যাখ্যা করো ।
ঘ. “কল্যাণী ও সুভা একই পরিস্থিতির শিকার হলেও উভয়ের প্রেক্ষাপট ও পরিণতি ভিন্ন *_ বিশ্লেষণ করো ।

---

### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘শুভা’ গল্পের কেন্দ্রীয় চরিত্রের নির্বাক হওয়ার মর্মবেদনা ব্যাখ্যা করো।**
> 💡 **উত্তর:** শুভা বোবা হওয়ায় সমাজের কাছে এক নীরব বোঝা বিবেচিত হতো। কিন্তু বোবা হলেও তার অনুভূতির জগৎ ছিল অত্যন্ত গভীর; প্রকৃতির সাথে তার গড়ে উঠেছিল এক নিখাদ বন্ধুত্বের সম্পর্ক।

> ❓ **প্রশ্ন: প্রকৃতি কীভাবে শুভার অপূর্ণতা পূরণ করত?**
> 💡 **উত্তর:** প্রকৃতির বিজন দ্বিপ্রহর, নদীর কলধ্বনি এবং গৃহপালিত জীবজন্তুরা শুভার না-বলা ভাষার অনুভূতি বুঝতে পারত এবং তার নিঃসঙ্গতাকে পরম মমতায় ভরিয়ে দিত।
