# ৪র্থ অধ্যায়: লাইব্রেরি (রবীন্দ্রনাথ ঠাকুর)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: রবীন্দ্রনাথ ঠাকুর*

---

## 📖 মূল পাঠ (গদ্য)

লাইব্রেরি
রবীন্দ্রনাথ ঠাকুর

মহাসমুদ্রের শত বৎসরের কল্লোল কেহ যদি এমন করিয়া বাঁধিয়া রাখিতে পারিত যে, সে ঘুমাইয়া
পড়া শিশুটির মতো চুপ করিয়া থাকিত, তবে সেই নীরব মহাশব্দের সহিত এই লাইবেরির তুলনা
হইত । এখানে ভাষা চুপ করিয়া আছে, প্রবাহ স্থির হইয়া আছে, মানবাত্সার অমর আলোক কালো
অক্ষরের শৃঙ্খলে কাগজের কারাগারে বাঁধা পড়িয়া আছে। ইহারা সহসা যদি বিদ্রোহী হইয়া উঠে,
নিস্তরূতা ভাঙিয়া ফেলে, অক্ষরের বেড়া দ্ধ করিয়া একবারে বাহির হইয়া আসে! হিমালয়ের মাথার
উপরে কঠিন বরফের মধ্যে যেমন কত কত বন্যা বাঁধা আছে, তেমনি এই লাইব্রেরির মধ্যে মানবহৃদয়ের

বিদ্যুৎকে মানুষ লোহার তার দিয়া বাঁধিয়াছে, কিন্তু কে জানিত মানুষ শব্দকে নিঃশব্দের মধ্যে
বাঁধিতে পারিবে । কে জানিত সংগীতকে, হৃদয়ের আশাকে, জাগ্রত আত্মার আনন্দধ্বনিকে, আকাশের
দৈববাণীকে সে কাগজে মুড়িয়া রাখিবে! কে জানিত মানুষ অতীতকে বর্তমানে বন্দি করিবে! অতলস্পর্শ
কালসমুদ্ধের উপর কেবল এক-একখানি বই দিয়া সাকো বাঁধিয়া দিবে!

লাইব্রেরির মধ্যে আমরা সহস্র পথের চৌমাথার উপরে দাঁড়াইয়া আছি। কোনো পথ অনন্ত সমুদ্রে
গিয়াছে, কোনো পথ অনন্ত শিখরে উঠিয়াছে, কোনো পথ মানবহদয়ের অতলস্পর্শে নামিয়াছে। যে
যে-দিকে ধাবমান হও, কোথাও বাধা পাইবে না। মানুষ আপনার পরিত্রাণকে এতটুকু জাগয়ার মধ্যে

শঙ্খের মধ্যে যেমন সমুদ্রের শব্দ শুনা যায়, তেমনি এই লাইব্রেরির মধ্যে কি হদয়ের উ্থানপতনের
শব্দ শুনিতেছ? এখানে জীবিত ও মৃত ব্যক্তির হৃদয় পাশাপাশি এক পাড়ায় বাস করিতেছে। বাদ
ও প্রতিবাদ এখানে দুই ভাইয়ের মতো একসঙ্গে থাকে। সংশয় ও বিশ্বাস, সন্ধান ও আবিষ্কার এখানে
“দেহে দেহে লগ্ন হইয়া বাস করে ।' এখানে দীর্ঘপ্রাণ স্বল্পপ্রাণ পরম ধের্য ও শান্তির সহিত জীবনযাত্রা
নির্বাহ করিতেছে, কেহ কাহাকেও উপেক্ষা করিতেছে না।

কত নদী সমুদ্র পর্বত উল্পজ্ঘন করিয়া মানবের কণ্ঠ এখানে আসিয়া পৌছিয়াছে- কত শত বৎসরের
প্রান্ত হইতে এই স্বর আসিতেছে। এসো এখানে এসো, এখানে আলোকের জন্মসংগীত গান হইতেছে।

অমৃতলোক প্রথম আবিষ্কার করিয়া যে যে মহাপুরুষ যে-কোনোদিন আপনার চারিদিকে মানুষকে ডাক
কণ্ঠই সহস্র ভাষায় সহস্র বংসরের মধ্য দিয়া এই লাইব্রেরির মধ্যে প্রতিধ্বনিত হইতেছে।

এই বের প্রান্ত হইতে আমাদের কি কিছু বলিবার নাই? মানবসমাজকে আমাদের কি কোনো সংবাদ
দিবার নাই? জগতের একতান সংগীতের মধ্যে বঙ্গদেশই কেবল নিস্তব্ধ হইয়া থাকিবে!

আমাদের পদপ্রান্তস্থিত সমুদ্র কি আমাদিগকে কিছু বলিতেছে না? আমাদের গঙ্গা কি হিমালয়ের শিখর
হইতে কৈলাসের কোনো গান বহন করিয়া আনিতেছে না? আমাদের মাথার উপরে কি তবে অনন্ত
নীলাকাশ নাই? সেখান হইতে অনন্তকালের চিরজ্যোতির্ময়ী নক্ষব্রলিপি কি কেহ মুছিয়া ফেলিয়াছে?



আমরা কি তাহার উত্তরে দুটি-চারটি চটি চটি ইংরেজি খবরের কাগজ লিখিব। সকল দেশ অসীম
কালের পটে নিজ নিজ নাম খুদিতেছে। বাঙালির নাম কি কেবল দরখাস্তের দ্বিতীয় পাতেই লেখা
থাকিবে! জড় অদৃষ্টের সহিত মানবাত্মার সংগ্রাম চলিতেছে, সৈনিকদিগকে আহ্বান করিয়া পৃথিবীর
লাউ-কুমড়া লইয়া মকদমা এবং আপিল চালাইতে থাকিব ।

বহু বৎসর নীরব থাকিয়া বঙ্গদেশের প্রাণ ভরিয়া উঠিয়াছে। তাহাকে আপনার ভাষায় একবার আপনার
কথাটি বলিতে দাও । বাঙালি-কণ্ঠের সহিত মিলিয়া বিশ্বসংগীত মধুরতর হইয়া উঠিবে।

---

### 📚 শব্দার্থ ও টীকা : কল্লোল- ঢেউ। শঙ্খ- শামুক জাতীয় সামুদ্রিক প্রাণী । উন্লুজ্ঘন- পার হওয়া, লঙ্ঘন
করা। অমৃতলোক-ন্বর্গ, বেহেশত। কৈলাস- হিন্দুধর্মের দেবতা শিবের বাসস্থান হিসেবে বর্ণিত

---

### 📝 পাঠ-পরিচিতি : “লাইব্রেরি" প্রবন্ধটি রবীন্দ্রনাথ ঠাকুরের বিচিত্র প্রবন্ধ গ্রন্থের অন্তর্ভূক্ত। এ প্রবন্ধে
রবীন্দ্রনাথ লাইব্রেরির গুরুত্ব তুলে ধরেছেন । তিনি লাইব্রেরিকে মহাসমুদ্ের কল্লোলধ্বনির সাথে তুলনা
দিয়েই আমরা আকাশের দৈববাণী থেকে মহাত্সাদের কথা পেয়ে থাকি । যাঁদের সানিধ্য আমাদের
কখনই পাওয়া সম্ভব নয়, বইয়ের ভেতর দিয়েই আমরা তাদের পেতে পারি । বই আমাদের অতীতের
সাথে সেতুবন্ধন গড়ে দেয়। এ বইয়ের স্থান হলো লাইব্বেরি। এ লাইবেরিতেই মানব হৃদয়ের
লাইবেরির মহত্টের কথা বর্ণনা করে লেখক বলেছেন- জগতের উদ্দেশ্যে কি আমাদেরও কিছু বলার
নেই? আমরা কি কেবল তুচ্ছ বিষয় নিয়ে কলহ করে বেড়াব। লেখক শেষে আশা ব্যক্ত করে বলেছেন-
বাঙালিরা জেগে উঠেছে। তারাও আপন ভাষায় লিখে বিশ্বের জ্ঞানভাগ্তার সমৃদ্ধ করে তুলবে।
আমাদের বই পাঠ এবং জ্ঞানের প্রতি আগ্রহী করে তোলে ।

কর্ম-অনুশীলন

১. তোমার এলাকার বা তোমার দেখা বা তুমি ব্যবহার কর এমন একটি পাঠাগার বা লাইব্রেরির
পরিচয় দাও ।

২. তোমাদের স্কুলের পাঠাগারটি কিভাবে আরও উন্নত করা যায়- সে বিষয়ে প্রস্তাব দাও ।

---

### ✍️ মূল পাঠ্যবইয়ের নমুনা প্রশ্ন
বহুনির্বাচনি প্রশ্ন
১। 'লাইবেরি' প্রবন্ধে লেখক মহাসমুদ্বের শত বৎসরের কল্লোলের সাথে কিসের তুলনা করেছেন?
ক.  মানবাআর খ. আলোকের
গ. লাইব্রেরির ঘ. সংগীতের

২। 'লাইবেরি' প্রবন্ধে “সহস্র পথের চৌমাথা” - বলতে কী বোঝানো হয়েছে?
ক. বহুজ্ঞানের সম্মিলন খ. বহু হৃদয়ের সম্মিলন
গ. বহুরাস্তার সম্মিলন ঘ. বহু জীবনের সম্মিলন

নিচের উদ্দীপকটি পড়ে ৩ ও ৪ নং প্রশ্নের উত্তর দাও।

হিন্দু মুসলমান বাঙালি। জন্মৃত্যুর বন্ধনে অভিন্ন সত্তা।
ক. হিংসা খ. বিদ্বেষ
গ. সংহতি ঘ. ঘৃণা
৪। উদ্দীপকে যে বিষয়বস্তর ইঙ্গিত রয়েছে তা 'লাইবেরি' প্রবন্ধের যে বাক্যে ব্যক্ত হয়েছে তা হলো -

1. জীবিত ও মৃত ব্যক্তির হৃদয় পাশাপাশি এক পাড়ায় বাস করিতেছে ।
1. বাদ ও প্রতিবাদ এখানে দুই ভাইয়ের মত একসঙ্গে থাকে।
11. সন্ধান ও আবিষ্কার এখানে দেহে দেহে লয় হইয়া বাস করে।

নিচের কোনটি ঠিক?
---

### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন
একজনের পক্ষে সর্ববিদ্যাবিশারদ হওয়া অসম্ভব । সেজন্য একেকজন একেক বিষয়ে পারদর্শিতা লাভ

করে । আবার যে-ব্যক্তি যে-বিদ্যায় পারদর্শিতা লাভ করে তার সবটুকু জ্ঞান মস্তিষ্কে ধারণ করাও

একজনের পক্ষে সম্ভব হয় না। তাই প্রয়োজন এমন কোনো উপায় উদ্ভাবনের, যার বদৌলতে দরকার

অনুযায়ী সমস্ত বিষয়ে একটা মোটামুটি জ্ঞান লাভ করা যায় । সেই থেকে প্রয়োজন দেখা দেয় জ্ঞান

সংরক্ষণের |

ক. কীসের মধ্যে সমুদ্রের শব্দ শোনা যায়?

খ. “জীবিত ও মৃত ব্যক্তির হৃদয় পাশাপাশি এক পাড়ায় বাস করিতেছে' - কথাটি বুঝিয়ে বল।

গ. উদ্দীপকে বর্ণিত জ্ঞান সংরক্ষণের কারণটি “লাইবেরি' প্রবন্ধের আলোকে তুলে ধর।

ঘ. “মানব হৃদয়ের বন্যাকে বেঁধে রাখার প্রয়োজনীয় দিকটিই যেন উদ্দীপকও লাইব্রেরি" প্রবন্ধের
মূল বক্তব্য” _ বিশ্লেষণ করো ।

