# ৫ম অধ্যায়: বই পড়া (প্রমথ চৌধুরী)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: প্রমথ চৌধুরী*

---

### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি : প্রমথ চৌধুরী ৭ই আগস্ট, ১৮৬৮ খিষ্টাব্দে যশোরে জন্মগ্রহণ করেন। তার পৈতৃক নিবাস ছিল
পাবনা জেলায় হরিপুর গ্রামে । তীর শিক্ষাজীবন ছিল অসাধারণ কৃতিতরপূর্ণ। তিনি ১৮৯০ খিষ্টাব্দে কলকাতা
বিশ্ববিদ্যালয় থেকে ইংরেজি সাহিত্যে প্রথম শ্রেণিতে এমএ ডিগ্রি লাভ করেন এবং পরে ব্যারিস্টারি পড়ার
জন্য বিলাত যান । বিলাত থেকে ফিরে এসে ব্যারিস্টারি পেশায় যোগদান না করে তিনি কিছুকাল ইংরেজি
সাহিত্যে অধ্যাপনা করেন এবং পরে সাহিত্যচর্চায় মনোনিবেশ করেন। তীর সাহিত্যিক ছদ্মনাম ছিল বীরবল।
তার সম্পাদিত সবুজপত্র (১৯১৪) বাংলা সাহিত্যে চলতি ভাষারীতি প্রবর্তনে অগ্রণী ভূমিকা পালন করে। বস্তত তারই
নেতৃত্বে বাংলা সাহিত্যে নতুন গদ্যধারা সূচিত হয়। তার উল্লেখযোগ্য গ্রন্থ : বীরবলের হালখাতা, রায়তের কথা,
চার-ইয়ারি কথা, আহুতি, এবন্ধ সংথহ, নীললোহিত, সনেট পঞ্গশৎ পদচারণ ইত্যাদি । প্রমথ চৌধুরী ২রা
সেপ্টেম্বর, ১৯৪৬ খিষ্টাব্দে কলকাতায় পরলোকগমন করেন। 

---

## 📖 মূল পাঠ (গদ্য)

বই পড়া
প্রমথ চৌধুরী



বই পড়া শখটা মানুষের সর্বশ্রেষ্ঠ শখ হলেও আমি কাউকে শখ হিসেবে বই পড়তে পরামর্শ দিতে
চাইনে । প্রথমত সে পরামর্শ কেউ গ্রাহ্য করবেন না, কেননা আমরা জাত হিসেবে শৌখিন নই।
দ্বিতীয়ত অনেকে তা কুপরামর্শ মনে করবেন কেননা আমাদের এখন ঠিক শখ করবার সময় নয়।
আমাদের এই রোগ-শোক, দুঃখ-দারিদ্যের দেশে সুন্দর জীবনধারণ করাই যখন হয়েছে প্রধান সমস্যা,
তখন সেই জীবনকেই সুন্দর করা, মহৎ করার প্রস্তাব অনেকের কাছে নিরর্থক এবং নির্মমও ঠেকবে।
কোনো সদুপায় আমরা চোখের সুমুখে দেখতে পাইনে । শিক্ষার মাহাত্্যে আমিও বিশ্বাস করি এবং
যিনিই যাই বলুন, সাহিত্যচর্চা যে শিক্ষার সর্বপ্রধান অঙ্গ সে বিষয়ে কোনো সন্দেহ নেই । লোকে যে তা
সন্দেহ করে, তার কারণ এ শিক্ষার ফল হাতে হাতে পাওয়া যায় না, অর্থাৎ তার কোনো নগদ বাজারদর
নেই। এই কারণে ডেমোক্রেসি সাহিত্যের সার্থকতা বোঝে না, বোঝে শুধু অর্থের সার্থকতা ।
ডেমোক্রেসির গুরুরা চেয়েছিলেন সকলকে সমান করতে কিন্তু তাদের শিষ্যরা তাদের কথা উলটো
বুঝে প্রতি জনেই হতে চায় বড়োমানুষ। একটি বিশিষ্ট অভিজাত সভ্যতার উত্তরাধিকারী হয়েও ইংরেজি
সভ্যতার সংস্পর্শে এসে আমরা ডেমোক্রেসির গুণগুলো আয়ত্ত করতে না পেরে তার দোষগুলো
আত্মসাৎ করেছি। এর কারণও স্পষ্ট । ব্যাধিই সংক্রামক, স্বাস্থ্য নয়। আমাদের শিক্ষিত সমাজের
যারা হাজারখানা ল-রিপোর্ট কেনেন, তারা একখানা কাব্যগ্রন্থও কিনতে প্রস্তুত নন; কেননা তাতে ব্যবসার
কোনো সুসার নেই। নজির না আউড়ে কবিতা আবৃত্তি করলে মামলা যে হারতে হবে সে তো জানা
কথা। কিন্তু যে কথা জজে শোনে না, তার যে কোনো মূল্য নেই, এইটেই হচ্ছে পেশাদারদের মহান্রান্তি ।
জ্ঞানের ভাগ্তার যে ধনের ভাণ্ডার নয়, এ সত্য তো প্রত্যক্ষ । কিন্ত সমান প্রত্যক্ষ না হলেও সমান সত্য
যে,এ যুগে যে জাতির জ্ঞানের ভাগ্ার শূন্য সে জাতির ধনের ভাড়েও ভবানী । তারপর যে জাতি মনে
বড়ো নয়, সে জাতি জ্ঞানেও বড়ো নয়; কেননা ধনের সৃষ্টি যেমন জ্ঞানসাপেক্ষ তেমনি জ্ঞানের সৃষ্টিও মন
সাপেক্ষ এবং মানুষের মনকে সরল, সচল, সরাগ ও সমৃদ্ধ করার ভার আজকের দিনে সাহিত্যের
অন্তরের স্বপ্ন ও সত্য, এই সকলের সমবায়ে সাহিত্যের জন্ম। অপরাপর শাস্ত্রের ভিতর যা আছে,

সে সব হচ্ছে মানুষের মনের ভগ্নাংশ; তার পুরো মনটার সাক্ষাৎ পাওয়া যায় শুধু সাহিত্যে । দর্শন বিজ্ঞান
ইত্যাদি হচ্ছে মনগঙ্গার তোলা জল, তার পূর্ণ শ্রোত আবহমানকাল সাহিত্যের ভেতরই সোল্লাসে
সবেগে বয়ে চলেছে এবং সেই গঙ্গাতে অবগাহন করেই আমরা আমাদের সকল পাপমুক্ত হব।

অতএব দীড়াল এই যে, আমাদের বই পড়তে হবে, কেননা বই পড়া ছাড়া সাহিত্যচর্চার উপায়ান্তর নেই।
ধর্মের চর্চা চাইকি মন্দিরের বাইরেও করা চলে, দর্শনের চর্চা গুহায়, নীতির চর্চা ঘরে এবং বিজ্ঞানের চর্চা
চিড়িয়াখানাতেও নয় । এইসব কথা যদি সত্য হয়, তাহলে আমাদের মানতেই হবে যে, সাহিত্যের মধ্যেই
উপকার হবে ।

আমাদের মনে হয়, এ দেশে লাইব্রেরির সার্থকতা হাসপাতালের চাইতে কিছু কম নয় এবং স্কুল
কলেজের চাইতে একটু বেশি । একথা শুনে অনেকে চমকে উঠবেন, কেউ কেউ আবার হেসেও
উঠবেন; কিন্তু আমি জানি, আমি রসিকতাও করছি নে, অদ্ভুত কথাও বলছি নে; যদিও এ বিষয়ে
লোকমত যে আমার মতের সমরেখায় চলে না, সে বিষয়ে আমি সম্পূর্ণ সচেতন । অতএব আমার
কথার আমি কৈফিয়ত দিতে বাধ্য । আমার বক্তব্য আমি আপনাদের কাছে নিবেদন করছি,তার সত্য

মিথ্যার বিচার আপনারা করবেন । সে বিচারে আমার কথা যদি না টেকে, তা হলে রসিকতা হিসেবেই
গ্রাহ্য করবেন ।

আমার বিশ্বাস, শিক্ষা কেউ কাউকে দিতে পারে না। সুশিক্ষিত লোক মাত্রই স্বশিক্ষিত। আজকের
বাজারে বিদ্যার দাতার অভাব নেই । এমনকি, এ ক্ষেত্রে দাতাকর্ণেরও অভাব নেই; এবং আমরা
আমাদের ছেলেদের তাদের দ্বারস্থ করেই নিশ্চিত থাকি, এই বিশ্বাসে যে, সেখান থেকে তারা এতটা
বিদ্যার ধন লাভ করে ফিরে আসবে,যার সুদে তার বাকি জীবন আরামে কাটিয়ে দিতে পারবে ।
কিন্ত এ বিশ্বাস নিতান্ত অমূলক । মনোরাজ্যেও দান গ্রহণসাপেক্ষ, অথচ আমরা দাতার মুখ চেয়ে
গ্রহীতার কথাটা একেবারেই ভুলে যাই। এ সত্য ভুলে না গেলে আমরা বুঝতুম যে, শিক্ষকের
সার্থকতা শিক্ষাদান করায় নয়, কিন্তু ছাত্রকে তা অর্জন করতে সক্ষম করায় । শিক্ষক ছাত্রকে শিক্ষার
পথ দেখিয়ে দিতে পারেন, তার কৌতুহল উদ্রেক করতে পারেন, তার বুদ্ধিবৃত্তিকে জাগ্তত করতে
পারেন, মনোরাজ্যের এশ্বর্ষের সন্ধান দিতে পারেন, তার জ্ঞানপিপাসাকে জলন্ত করতে পারেন,
এর বেশি আর কিছু পারেন না। যিনি যথার্থ গুরু, তিনি শিষ্যের আত্মাকে উদ্‌বোধিত করেন এবং তার
অন্তর্নিহিত সকল প্রচ্ছন্ন শক্তিকে মুক্ত এবং ব্যক্ত করে তোলেন। সেই শক্তির বলে সে নিজের মন নিজে
গড়ে তোলে, নিজের অভিমতবিদ্যা নিজে অর্জন করে। বিদ্যার সাধনা শিষ্যকে নিজে করতে হয়। গুরু
উত্তরসাধক মাত্র ।

আমাদের স্কুল-কলেজের শিক্ষার পদ্ধতি ঠিক উলটো । সেখানে ছেলেদের বিদ্যে গেলানো হয়, তারা
তাজীর্ণ করতে পারুক আর নাই পারুক। এর ফলে ছেলেরা শারীরিক ও মানসিক মন্দাগ্নিতে
জীর্নশীর্ণ হয়ে কলেজ থেকে বেরিয়ে আসে। একটা জানাশোনা উদাহরণের সাহায্যে ব্যাপারটা
পরিষ্কার করা যাক। আমাদের সমাজে এমন অনেক মা আছেন, যারা শিশু সন্তানকে ক্রমান্বয়ে
গরুর দুধ গেলানোটাই শিশুর স্বাস্থ্যরক্ষার ও বলবৃদ্ধির সর্বপ্রধান উপায় মনে করেন। গোদুগ্ধ অবশ্য



অতিশয় উপাদেয় পদার্থ, কিন্তু তার উপকারিতা যে ভোক্তার জীর্ণ করবার শক্তির উপর নির্ভর করে
এ জ্ঞান ও শ্রেণির মাতৃকুলের নেই। তাদের বিশ্বাস ও-বন্ত পেটে গেলেই উপকার হবে । কাজেই শিশু
যদি তা গিলতে আপত্তি করে তা হলে সে যে ব্যাদড়া ছেলে, সে বিষয়ে আর বিন্দুমাত্র সন্দেহ থাকে না।
অতএব তখন তাকে ধরে-বেঁধে জোর জবরদস্তি করে দুধ খাওয়ানোর ব্যবস্থা করা হয়। শেষটায় সে
যখন এই দুগ্ধপান ক্রিয়া হতে অব্যাহতি লাভ করবার জন্য মাথা নাড়তে, হাত-পা ছুড়তে শুরু করে,
তখন গ্নেহময়ী মাতা বলেন “আমার মাথা খাও, মরামুখ দেখ, এই ঢোক, আর এক ঢোক, আর
এক ঢোক" ইত্যাদি । মাতার উদ্দেশ্য যে খুব সাধু, সে বিষয়ে কোনো সন্দেহ নেই, কিন্তু এ
বিষয়েও কোনো সন্দেহ নেই যে, উক্ত বলা কওয়ার ফলে মা শুধু ছেলের যকৃতের মাথা খান এবং
পদ্ধতিটাও এ একই ধরনের । এর ফলে কত ছেলের সুস্থ সরল মন যে ইনফ্যান্টাইল লিভারে গতাসু
হচ্ছে তা বলা কঠিন। কেননা দেহের মৃত্যুর রেজিস্টারি রাখা হয়, আত্মার মৃত্যুর হয় না।

আমরা কিন্তু এই আত্মার অপমৃত্যুতে ভীত হওয়া দূরে থাক, উৎফুল্ হয়ে উঠি। আমরা ভাবি দেশে
যত ছেলে পাশ হচ্ছে তত শিক্ষার বিস্তার হচ্ছে। পাশ করা ও শিক্ষিত হওয়া এক বন্ত নয়, এ
যে, এক সময়ে ফরাসি দেশে শিক্ষা-পদ্ধতি এতই বেয়াড়া ছিল যে, সে যুগে 17781706 %/85 98৬6৫
51767 110.9; অর্থাৎ যারা পাশ করতে পারেনি বা চায় নি তারাই ফ্রা্সকে রক্ষা করেছে। এর
কারণ, হয় তাদের মনের বল ছিল বলে কলেজের শিক্ষাকে তারা প্রত্যাখ্যান করেছিল, নয় সে
দল থেকে সে যুগের ফ্রালের যত কৃতকর্মা লোকের আবির্ভাব হয়েছিল ।

সে যুগে ফ্রান্সে কী রকম শিক্ষা দেওয়া হতো তা আমার জানা নেই। তবুও আমি জোর করে বলতে
পারি যে,এ যুগে আমাদের স্কুল কলেজে শিক্ষার যে রীতি চলছে, তার চাইতে সে শিক্ষাপদ্ধতি
কখনোই নিকৃষ্ট ছিল না। সকলেই জানেন যে, বিদ্যালয়ে মাস্টার মহাশয়েরা নোট দেন এবং সেই
নোট মুখস্থ করে ছেলেরা হয় পাশ। এর জুড়ি আর একটি ব্যাপারও আমাদের দেশে দেখা যায়।
পর্যন্ত গলাধঃকরণ করে । তারপর একে একে সবগ্তলো উগলে দেয়। এর ভেতর যে অসাধারণ
কৌশল আছে, সে বিষয়ে কোনো সন্দেহ নেই। কিন্ত এই গেলা আর ওগলানো দর্শকের কাছে
তামাশা হলেও বাজিকরের কাছে তা প্রাণান্ত ব্যাপার | ও কারদানি করা তার পক্ষে যেমন কষ্টসাধ্য,
তেমনি অপকারী । বলা বাহুল্য, সে বেচারা লোহার গোলাগুলোর এক কণাও জীর্ণ করতে পারে না।
বিদ্যালয়ে গলাধঃকরণ করে পরীক্ষালয়ে তা উদ্গীরণ করে দেয় । এ জন্য সমাজ তাদের বাহবা দেয় দিক,
কিন্ত মনে যেন না ভাবে যে, এতে জাতির প্রাণশক্তি বাড়ছে। স্কুল-কলেজে শিক্ষা যে অনেকাংশে ব্যর্থ
সে বিষয়ে প্রায় অধিকাংশ লোকই একমত | আমি বলি, শুধু ব্যর্থ নয়, অনেক স্থলে মারাত্মক । কেননা
আমাদের স্কুল-কলেজের ছেলেদের স্বশিক্ষিত হবার সে সুযোগ দেয় না, শুধু তাই নয়, স্বশিক্ষিত
হবার শক্তি পর্যন্ত নষ্ট করে। আমাদের শিক্ষাযন্ত্রের মধ্যে যে যুবক নিম্পেষিত হয়ে বেরিয়ে আসে,

তার আপনার বলতে আর বেশি কিছু থাকে না, যদি না তার প্রাণ অত্যন্ত কড়া হয়। সৌভাগ্যের
বিষয়, এই ক্ষীণপ্রাণ জাতির মধ্যেও জনকতক এমন কঠিন প্রাণের লোক আছে, এহেন
শিক্ষাপদ্ধতিও তাদের মনকে জখম করলেও একেবারে বধ করতে পারে না।

আমি লাইব্রেরিকে স্কুল-কলেজের ওপরে স্থান দিই এই কারণে যে, এ স্থলে লোকে স্বেচ্ছায়
স্বচ্ছন্দচিত্তে স্বশিক্ষিত হবার সুযোগ পায়; প্রতিটি লোক তার স্বীয় শক্তি ও রুচি অনুসারে নিজের
আমাদের যে অপকার করছে সে অপকারের প্রতিকারের জন্য শুধু নগরে নগরে নয়, গ্রামে গ্রামে
লাইব্রেরির প্রতিষ্ঠা করা কর্তব্য । আমি পূর্বে বলেছি যে, লাইব্রেরি হাসপাতালের চাইতে কম উপকারী
অতঃপর আপনারা জিজ্ঞাসা করতে পারেন যে, বই পড়ার পক্ষ নিয়ে এ ওকালতি করবার, বিশেষত
প্রাচীন নজির দেখাবার কী প্রয়োজন ছিল? বই পড়া যে ভালো, তা কে না মানে? আমার উত্তর-
সকলে মুখে মানলেও কাজে মানে না । মুসলমান ধর্মে মানবজাতি দুই ভাগে বিভক্ত । যারা কেতাবি,
আর এক যারা তা নয়। বাংলায় শিক্ষিত সমাজ যে পূর্বদলভুক্ত নয়, একথা নির্ভয়ে বলা যায় না;
আমাদের শিক্ষিত সম্প্রদায় মোটের ওপর বাধ্য না হলে বইস্পর্শ করেন না। ছেলেরা যে নোট
পড়ে এবং ছেলের বাপেরা যে নজির পড়েন, দুই-ই বাধ্য হয়ে, অর্থাৎ পেটের দায়ে। সেইজন্য
সাহিত্যচর্চা দেশে একরকম নেই বললেই হয়; কেননা, সাহিত্য সাক্ষাতভাবে উদরপূর্তির কাজে
লাগে না। বাধ্য হয়ে বই পড়ায় আমরা এতটা অভ্যস্ত হয়েছি যে, কেউ স্বেচ্ছায় বই পড়লে আমরা
তাকে নিক্বর্মার দলেই ফেলে দিই; অথচ একথা কেউ অস্বীকার করতে পারবেন না, যে জিনিস স্বেচ্ছায়
না করা যায়, তাতে মানুষের মনের সন্তোষ নেই । একমাত্র উদরপূর্তিতে মানুষের সম্পূর্ণ মনস্তষ্টি হয়
না। একথা আমরা সকলেই জানি যে, উদরের দাবি রক্ষা না করলে মানুষের দেহ বাঁচে না; কিন্তু
একথা আমরা সকলে মানিনে যে, মনের দাবি রক্ষা না করলে মানুষের আত্মা বাঁচে না। দেহরক্ষা
রয়েছে যে মানুষের প্রাণ-মনের সম্পর্ক যত হারায় ততই তা দুর্বল হয়ে পড়ে। মনকে সজাগ ও
সবল রাখতে না পারলে জাতির প্রাণ যথার্থ স্কুর্তিলাভ করে না; তারপর যে জাতি যত নিরানন্দ
সে জাতি তত নিজর্বি। একমাত্র আনন্দের স্পর্শেই মানুষের মনপ্রাণ সজীব, সতেজ ও সরাগ হয়ে
ওঠে । সুতরাং সাহিত্যচর্চার আনন্দ থেকে বঞ্চিত হওয়ার অর্থ হচ্ছে, জাতির জীবনীশক্তির হাস করা।
অতএব, কোনো নীতির অনুসারেই তা কর্তব্য হতে পারে না। অর্থনীতিরও নয়, ধর্মনীতিরও নয় ।

কাব্যামৃতে যে আমাদের অরুচি ধরেছে সে অবশ্য আমাদের দোষ নয়, আমাদের শিক্ষার দৌষ। যার
আনন্দ নেই সে নিজীবি একথা যেমন সত্য, যে নিজববি তারও আনন্দ নেই, সে কথাও তেমনি সত্য ।
আমাদের শিক্ষাই আমাদের নিবি করেছে। জাতীয় আত্মরক্ষার জন্য এ শিক্ষার উলটো টান যে


আমাদের টানতে হবে, এ বিষয়ে আমি নিঃসন্দেহ। এই বিশ্বাসের বলেই আমি স্বেচ্ছায় সাহিত্যচর্চার
সপক্ষে এত বাক্য ব্যয় করলুম ।সে বাক্যে আপনাদের মনোরঞ্জন করতে সক্ষম হয়েছি কিনা জানিনে।
সম্ভবত হইনি । কেননা, আমাদের দুরবস্থার কথা যখন স্মরণ করি, তখন খালি কোমল সুরে আলাপ
করা আর চলে না; মনের আক্ষেপ প্রকাশ করতে মাঝে মাঝেই কড়ি লাগাতে হয়। ॥ [সংক্ষেপিত]

