# ৬ষ্ঠ অধ্যায়: অভাগীর স্বর্গ (শরৎচন্দ্র চট্টোপাধ্যায়)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: শরৎচন্দ্র চট্টোপাধ্যায়*

---

### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি : শরৎচন্দ্র চট্টোপাধ্যায় ভারতের পশ্চিমবঙ্গ রাজ্যের হুগলি জেলার দেবানন্দপুর গ্রামে
১৫ই সেপ্টেম্বর, ১৮৭৬ খিষ্টাব্দে জন্গ্রহণ করেন। আর্থিক সংকটের কারণে এফএ শ্রেণিতে পড়ার সময় তার
ছাত্রজীবনের অবসান ঘটে । তিনি কিছুদিন ভবঘুরে হয়ে বিভিন্ন জায়গায় ভ্রমণ করেন। পরে ১৯০৩ খিষ্টাব্দে
ভাগ্যের সন্ধানে বার্মা বের্তমানে মায়ানমার) যান এবং রেঙ্গুনে আ্যাকাউন্ট্যান্ট জেনারেলের অফিসে কেরানি
পদে চাকরি করেন। প্রবাস জীবনেই তার সাহিত্য-সাধনা শুরু এবং তিনি অল্পদিনেই খ্যাতি লাভ করেন।
১৯১৬ খিষ্টাব্দে তিনি কলকাতায় ফিরে আসেন এবং নিয়মিতভাবে সাহিত্য-সাধনা করতে থাকেন । গল্প,
উপন্যাস রচনার পাশাপাশি তিনি কিছু প্রবন্ধ রচনা করেন। তিনি রাজনৈতিক আন্দোলনেও যোগ দিয়েছিলেন,
দেনা পাওনা, পথের দাবী, শেষ প্রশ্ন ইত্যাদি । শরৎচন্দ্র ১৬ই জানুয়ারি, ১৯৩৮ খিষ্টাব্দে মৃত্যুবরণ করেন |

