### ✍️ মূল পাঠ্যবইয়ের সৃজনশীল প্রশ্ন

এই নিষ্ঠুর অভিযোগে গফুর যেন বাক্রোধ হইয়া গেল। ক্ষণেক পরে ধীরে ধীরে কহিল, কাহন
খানেক খড় এবার ভাগে পেয়েছিলাম । কিন্তু গেল সনের বকেয়া বলে কর্তামশায় সব ধরে রাখলেন?
কেঁদে কেটে হাতে পায়ে পড়ে বললাম, বাবু মশাই, হাকিম তুমি, তোমার রাজত্ব ছেড়ে আর
পালাব কোথায়? আমাকে পণদশেক বিচুলি না হয় দাও । চালে খড় নেই। বাপ বেটিতে থাকি,
তাও না হয় তালপাখার গৌজাগাজা দিয়ে এ বর্ধা কাটিয়ে দেব, কিন্তু না খেতে পেয়ে আমার মহেশ
যে মরেযাবে।

কাঙালীর বাবার নাম কী?

“তোর হাতের আগ্তন যদি পাই, আমিও সগ্যে যাব" _উক্তিটি ব্যাখ্যা করো ।

উদ্দীপকে “অভাগীর স্বর্গ” গল্পের যে সমাজচিত্রের ইঙ্গিত রয়েছে-তা ব্যাখ্যা করো ।
“কাঙালীর সঙ্গে উদ্দীপকের গফুরের সাদৃশ্য থাকলেও কাঙালী সম্পূর্ণরূপে গফুরের প্রতিনিধিত্
করে না'_ মন্তব্যটির যথার্থতা নিরূপণ করো ।

