### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘অভাগীর স্বর্গ’ গল্পে শরৎচন্দ্র চট্টোপাধ্যায় সমাজের কোন বৈষম্য তুলে ধরেছেন?**
> 💡 **উত্তর:** লেখক তৎকালীন সামন্ততান্ত্রিক সমাজের জাতপাত, শ্রেণিভেদ এবং দরিদ্র নিম্নবর্ণের মানুষের প্রতি তথাকথিত উচ্চবর্ণের অমানবিক ও নির্মম নিষ্ঠুরতাকে মর্মস্পর্শী ভাষায় তুলে ধরেছেন।

> ❓ **প্রশ্ন: কাঙ্গালীর মায়ের শেষ ইচ্ছা কী ছিল এবং কেন তা পূরণ হলো না?**
> 💡 **উত্তর:** কাঙ্গালীর মায়ের ইচ্ছা ছিল মৃত্যুর পর স্বামীর হাতে মুখাগ্নি পেয়ে স্বর্গে যাওয়া; কিন্তু দারিদ্র্য ও উচ্চবর্ণের নিষ্ঠুর বাধার কারণে তার সৎকারের জন্য সামান্য কাঠটুকুও জোটেনি।
