# ৭ম অধ্যায়: নিরীহ বাঙালি (রোকেয়া সাখাওয়াত হোসেন)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: রোকেয়া সাখাওয়াত হোসেন*

---

### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি : রোকেয়া সাখাওয়াত হোসেন ৯ই ডিসেম্বর, ১৮৮০ খিষ্টাব্দে রংপুর জেলার পায়রাবন্দ
ছোটবেলায় বড় বোন করিমুননেসা বেগম রোকেয়াকে বাংলা শিক্ষায় সাহায্য করেন। পরে তিনি বড় ভাই ইব্রাহিম
সাবেরের তত্বাবধানে ইংরেজি শেখেন। বিহারের অন্তর্গত ভাগলপুরের সৈয়দ সাখাওয়াত হোসেনের সঙ্গে
বিবাহের পর তিনি বেগম রোকেয়া সাখাওয়াত হোসেন নামে পরিচিত হন। স্বামীর প্রেরণায় তিনি সাহিত্যচর্চা
শুরু করেন। সমকালীন মুসলমান সমাজে প্রচলিত কুসংস্কারের বিরুদ্ধে তিনি লেখনী ধারণ করেন । মুসলিম নারী
জাগরণে তিনি অগ্রণী ভূমিকায় অবতীর্ণ হন। সাখাওয়াত মেমোরিয়াল গার্লস স্কুল ও আনজুমান -ই-খাওয়াতীন
-ই-ইসলাম প্রতিষ্ঠা করে তিনি মুসলমান নারীদের শিক্ষা ও সংস্কৃতির পথে অগ্রসর হতে সাহায্য করেন। পদ্ররাগ,
অবরোধবাসিনী, মতিচুর, সুলতানার স্বপ্ন ইত্যাদি তীর উল্লেখযোগ্য গ্রন্থ । ৯ই ডিসেম্বর, ১৯৩২ খিষ্টাব্দে রোকেয়া
সাখাওয়াত হোসেন মৃত্যুবরণ করেন। 

