## 📖 মূল পাঠ (গদ্য)

নিরীহ বাঙালি



আমরা দুর্বল নিরীহ বাঙালি । এই বাঙালি শব্দে কেমন সুমধুর তরল কোমল ভাব প্রকাশ হয় । আহা!
এই অমিয়সিক্ত বাঙালি কোন্‌ বিধাতা গড়িয়াছিলেন? কুসুমের সৌকুমার্য, চন্দ্রের চন্দ্রকা, মধুর মাধুরী,
যুথিকার সৌরভ, সুপ্তির নীরবতা, ভূধরের অচলতা, নবনীর কোমলতা, সলিলের তরলতা- এক
কথায় বিশ্বজগতের সমুদয় সৌন্দর্য এবং খ্লিপ্ধতা লইয়া বাঙালি গঠিত হইয়াছে! আমাদের নামটি
যেমন শ্রুতিমধুর তদ্রপ আমাদের সমুদয় ক্রিয়াকলাপও সহজ ও সরল।

বঙ্গদেশ তাহার বৈঠকখানা (01951 10011) এবং বাঙালি তাহাতে সাজসজ্জা (0195/105
10010] 9011)! যদি ভারতবর্ধকে একটা সরোবর মনে করেন, তবে বাঙালি তাহাতে পদ্মিনী। যদি
ভারতবর্ষকে একখানা উপন্যাস মনে করেন, তবে বাঙালি তাহার নায়িকা! ভারতের পুরুষ সমাজে
বাঙালি পুরুষিকা! অতএব আমরা মূর্তিমান কাব্য ।

আমাদের খাদ্যদ্রব্যগুলি _পুঁইশাকের ডাটা, সজিনা ও পুঁটি মৎস্যের ঝোল-অতিশয় সরস।
আমাদের খাদ্যদ্রব্যগুলি -ঘৃত, দুগ্ধ, ছানা, নবনীত, ক্ষীর, সর, সন্দেশ ও রসগোল্লা-অতিশয় সুস্বাদু ।
আমাদের দেশের প্রধান ফল, আমর ও কীঠাল-রসাল এবং মধুর। অতএব আমাদের খাদ্যসামগ্্রী
ত্রিগুণাত্ক-সরস, সুস্বাদু, মধুর ।

খাদ্যের গুণ অনুসারে শরীরের পুষ্টি হয় । তাই সজিনা যেমন বীজবহুল, আমাদের দেশে তেমনই ভুূঁড়িটি
স্থল। নবনীতে কোমলতা অধিক, তাই আমাদের স্বভাবের ভীরুতা অধিক। শারীরিক সৌন্দর্য সম্বন্ধে
অধিক বলা নিষ্প্রয়োজন; এখন পোষাক পরিচ্ছদের কথা বলি ।

আমাদের বর অঙ্গ যেমন তৈলসিক্ত নবনিগঠিত সুকোমল, পরিধেয়ও তদ্ধপ অতি সৃক্ষম শিমলার
ধুতি ও চাদর। ইহাতে বাযুসঞ্চালনের (৮6171191101 এর) কোন বাধা বিঘ্ন হয় না! আমরা সময়
সময় সভ্যতার অনুরোধে কোট শার্ট ব্যবহার করি বটে, কারণ পুরুষমানুষের সবই সহ্য হয়।

কিন্তু আমাদের অর্ধাঙগী-হেমাঙ্গী, কৃষ্াঙ্গীগণ তদানুকরণে ইংরেজ ললনাদের নির্লজ্জ পরিচ্ছদ
(শেমিজ জ্যাকেট) ব্যবহার করেন না। তাহারা অতিশয় সুকুমারী ললিতা লজ্জাবতী লতিকা, তাই
অতি মসৃণ ও সৃক্ষ্ম “হাওয়ার শাড়ি' পরেন। বাঙালির সকল বস্তই সুন্দর, স্বচ্ছ ও সহজলব্ধ ।

বাঙালির গুণের কথা লিখিতে হইলে অনন্ত মসী, কাগজ ও অক্লান্ত লেখকের আবশ্যক | তবে সংক্ষেপে
দুটি চারিটা গুণের বর্ণনা করি।

ধনবৃদ্ধির দুই উপায়, বাণিজ্য ও কৃষি। বাণিজ্য আমাদের প্রধান ব্যবসায়। কিন্তু তাই বলিয়া
অপার সাগরে ভাসাইয়া দিয়া নৈরাশ্যের ঝঞ্জাবাতে ওতপ্রোত হই না। আমরা ইহাকে বোণিজ্য)
সহজ ও স্বল্লায়াসসাধ্য করিয়া লইয়াছি। অর্থাৎ বাণিজ্য ব্যবসায়ে যে কঠিন পরিশ্রম আবশ্যক,তাহা
বর্জন করিয়াছি। এই জন্য আমাদের দোকানে প্রয়োজনীয় জিনিস নাই, শুধু বিলাসদ্রব্য-নানাবিধ
কেশতৈল ও নানাপ্রকার রোগবর্ধক উষধ এবং রাঙা পিতলের অলঙ্কার, নকল হীরার আংটি, বোতাম
ইত্যাদি কিক্রয়ার্থ মজুদ আছে। ঈদৃশ ব্যবসায়ে কায়িক পরিশ্রম নাই । আমরা খাটি সোনা রুপা বা হিরা
জওয়াহেরাৎ রাখি না, কারণ টাকার অভাব । বিশেষত আজি কালি কোন জিনিসটার নকল না হয়?

যখনই কেহ একটু যত্বু পরিশ্রম স্বীকার পূর্বক “দীর্ঘকেশী” তৈল প্রস্তুত করেন, অমনই আমরা
স্নিগ্ধকারী” ওষধ আছে, “মস্তিষ্ক উষ্তকারী” দ্রব্যও আছে। এক কথায় বলি, যত প্রকারের নকল
ও নিষ্প্রয়োজনীয় জিনিস হইতে পারে, সবই আছে। আমরা ধান্য তগুলের ব্যবসায় করি না, কারণ
তাহাতে পরিশ্রম আবশ্যক ।

আমাদের অন্যতম ব্যবসায়_পাস বিক্রয় । এই পাস বিক্রেতার নাম “বর” এবং ক্রেতাকে “শ্বশুর” বলে।
এক একটি পাসের মূল্য কত জান ? “অর্ধেক রাজত্‌ ও এক রাজকুমারী” । এম.এ. পাশ অমূল্যরত্ু,
ইহা যে সে ক্রেতার ক্রেয় নহে। নিতান্ত সস্তা দরে বিক্রয় হইলে, মূল্য-এক রাজকুমারী এবং সমুদয়
রাজতৃ । আমরা অলস, তরলমতি, শ্রমকাতর, কোমলাঙ্গ বাঙালি কিনা তাই ভাবিয়া দেখিয়াছি,
সশরীরে পরিশ্রম করিয়া মুদ্বালাভ করা অপেক্ষা (01 0০1) শ্বশুরের যথাসর্বস্ব লুগ্ঠন করা সহজ।

এখন কৃষিকার্ষের কথা বলি। কৃষি দ্বারা অন্নবৃদ্ধি হইতে পারে। কিন্তু আমরা ভাবিয়া দেখিয়াছি
কৃষিবিভাগের কার্ষ (৪2110016016) করা অপেক্ষা মস্তিষ্ক উর্বর (0181 ০010০) করা সহজ।
অর্থাৎ কর্কশ উর্বর ভূমি কর্ষণ করিয়া ধান্য উৎপাদন করা অপেক্ষা মুখস্থ বিদ্যার জোরে অর্থ উৎপাদন
করা সহজ। এবং কৃষিকার্ষে পারদর্শিতা প্রদর্শন করা অপেক্ষা কেবল ৬.২./১.0 পাশ করা সহজ।
