তারপর আমরা মূর্তিমান আলস্য-আমাদের গৃহিণীগণ এ বিষয়ে অগ্রণী । কেহ কেহ শ্রীমতীদিগকে
স্বহস্তে রন্ধন করিতে অনুরোধ করিয়া থাকেন। কিন্তু বলি, আমরা যদি রৌদ্রতাপ সহ্য করিতে
না পারি, তবে আমাদের অধাঙ্গিগণ কিরূপে অগ্নির উত্তাপ সহিবেন? আমরা কোমলাঙ্গ-তাহারা
কোমলাঙ্গী; আমরা পাঠক,তাহারা পাঠিকা; আমরা লেখক, তাহারা লেখিকা । অতএব আমরা পাচক
না হইলে তাঁহারা পাচিকা হইবেন কেন? সুতরাং যে লক্ষ্মীছাড়া দিব্যাঙ্গনাদিগকে রন্ধন করিতে বলে,
তাহার ত্রিবিধ দণ্ড হওয়া উচিত। যথা তাহাকে (১) তুষানলে দগ্ধ কর, অতঃপর (২) জবেহ কর,
তারপর (৩) ফীসি দাও!

অপেক্ষা লেখিকার সংখ্যা বেশি। তাই কবিতার স্রোতে বিনা কারণে অশ্রপ্রবাহ বেশি বহিয়া থাকে ।
আমরা পদ্য লিখিতে বসিলে কোন্‌ বিষয়টা বাদ দিই? “ভগ্ন শূর্ণ”, “জীর্ণ কাথা”, “পুরাতন চটিজুতা”
_কিছুই পরিতাজ্য নহে । আমরা আবার কত নতুন শব্দের সৃষ্টি করিয়াছি; যথা-“অতি শুত্রনীলাম্বর”,
“সাশ্রুসজলনয়ন” ইত্যাদি । শ্রীমতীদের করুণ বিলাপ-প্রলাপপূর্ণ পদ্যের “অশ্রজলের” বন্যায়
আর আত্মপ্রশংসা কত করিব? এখন উপসংহার করি ।

