### 📚 শব্দার্থ ও টীকা : সৌকুমার্য- সৌন্দর্য ঝঞ্চীবাতে- ঝঞ্জার বাতাসে। কুস্তলীন, কেশলীন- লেখকের
চাল। কালিডর, মিন্ক অভ রোজ, ভিনোলিয়া পাউডার- সৌন্দর্যবর্ধক সামগ্রী। দিব্যাঙ্গনা- স্বর্গের

রূপসী। হুরপরি। শুভ্রনীলাম্বর- পরিষ্কার নীল আকাশ। সাশ্রুসজলনয়ন- জলভরা চোখ। আত্মপ্রশংসা-
নিজের প্রশংসা ।

পাঠ -পরিচিতি : “নিরীহ বাঙালি" প্রবন্ধটিতে রোকেয়া সাখাওয়াত হোসেন বাঙালি নারী পুরুষের
প্রাত্যহিক জীবনাচরণের বিভিন্ন দিক হাস্য-রসাত্মকভাবে বর্ণনা করেছেন। বাঙালি পুরুষগণের
অলসপ্রিয়তা, শারীরিক পরিশ্রমে অনীহা, বাগাড়ম্বর আচরণ সম্পর্কে আলোচনা যেমন রয়েছে, তেমনি
নারীদের অহেতুক রূপচর্চা, পরচর্চা এবং নিজেদের অবলা প্রমাণ করার সর্বাত্বক প্রচেষ্টার প্রতি
আলোচনাও রয়েছে। প্রকৃতপক্ষে ব্যঙ্গাত্মক এ প্রবন্ধের মাধ্যমে রোকেয়া সাখাওয়াত হোসেন বাঙালি
প্রবন্ধটি আমাদের ইতিবাচক ও গুরুত্বপূর্ণ কাজের প্রতি মনোযোগী হবার শিক্ষা দেয়।

