# ৮ম অধ্যায়: পল্লিসাহিত্য (মুহম্মদ শহীদুল্লাহ)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: মুহম্মদ শহীদুল্লাহ*

---

## 📖 মূল পাঠ (গদ্য)

পল্লিসাহিত্য
মুহম্মদ শহীদুল্লাহ

[লেখক -পরিচিতি : মুহম্মদ শহীদুল্লাহ ১০ই জুলাই, ১৮৮৫ খিষ্টাব্দে পশ্চিম বঙ্গের চব্বিশ পরগনা জেলার
বসিরহাট মহকুমার পেয়ারা গ্রামে জনুগ্রহণ করেন। তিনি কলকাতা সিটি কলেজ থেকে সংস্কৃতে বিএ অনার্স
পাস করেন। কলকাতা বিশ্ববিদ্যালয় থেকে তিনি তুলনামূলক ভাষাতত্বে এমএ ডিগ্রি লাভ করেন । মুহম্মদ
শহীদুল্লাহ্‌ প্যারিসের সোরবন বিশ্ববিদ্যালয় থেকে ভাষাতত্তে ডিপ্লোমা এবং ডি লিট লাভের গৌরব অর্জন
করেন। তিনি বাংলাদেশের বিভিন্ন কলেজ ও বিশ্ববিদ্যালয়ে বাংলা ভাষা ও সাহিত্যের অধ্যাপক এবং অধ্যক্ষরূপে
নিয়োজিত ছিলেন। অসামান্য প্রতিভাধর মুহম্মদ শহীদুল্লাহ ছিলেন সুপপ্তিত ও ভাষাবিদ। প্রাচীন ভাষা ও
সাহিত্য সম্পর্কে দুরূহ ও জটিল সমস্যার যুক্তিপূর্ণ ব্যাখ্যা ও বিশ্লেষণে তিনি অসামান্য পাপ্তিত্যের পরিচয়
দিয়েছেন। বাংলা ভাষার ইতিবৃত্ত, বাংলা সাহিত্যের কথা (দুই খও) এবং বাংলা ভাষার ব্যাকরণ তার
উল্লেখযোগ্য গ্রন্থ ।তার অন্যতম কালজয়ী সম্পাদনা গ্রন্থ বাংলাদেশের আঞ্চলিক ভাষার অভিধান । শিশু
পত্রিকা আঙুর তারই সম্পাদনায় প্রকাশিত হয়। এ ছাড়া পাঠ্যপুস্তক অনুবাদ এবং নানা মৌলিক রচনায়
তিনি তার দক্ষতার পরিচয় রেখেছেন। ১৩ই জুলাই, ১৯৬৯ খিষ্টাব্দে ঢাকায় মুহম্মদ শহীদুল্লাহ্র জীবনাবসান
ঘটে ॥]

ভঙ্গিময় হিলাদুলা প্রচুর পরিমাণে শহরের অভাব এখানে পূর্ণ করে দিচ্ছে। পন্লির ঘাটেমাঠে, পল্লির
আলোবাতাসে, পল্লির প্রত্যেক পরতে পরতে সাহিত্য ছড়িয়ে আছে। কিন্তু বাতাসের মধ্যে বাস করে
যেমন আমরা ভুলে যাই বায়ু- সাগরে আমরা ডুবে আছি, তেমনি পাড়াগীয়ে থেকে আমাদের মনেই
হয় না যে কত বড়ো সাহিত্য ও সাহিত্যের উপকরণ ছড়িয়ে আছে।

শ্রদ্ধেয় ডক্টর দীনেশচন্দ্র সেন মৈমনসিংহ গীতিকা সংগ্রহ করে দেখিয়েছেন, সাহিত্যের কী এক অমূল্য
জগতের সঙ্গে চেনাশোনা করিয়ে দেবে? আজ যদি বাংলাদেশের প্রত্যেক পল্লি থেকে এইসব অজানা
অচেনা কবিদের গাথা সংগ্রহ করে প্রকাশ করা হতো, তাহলে দেখা যেত বাংলার মুসলমানও সাহিত্য
সম্পদে কত ধনী। কিন্তু হায়! এ কাজের জন্য স্বেচ্ছাসেবক দল কই?

আমরা পল্লিগ্রামে বুড়োবুড়ির মুখে কোনো বিল্লিমুখর সন্ধ্যাকালে যেসব কথা শুনতে শুনতে
আলাউদ্দিনের আশ্চর্য প্রদীপ, আলিবাবা ও চল্লিশ দস্যু প্রভৃতির চেয়ে পন্নির উপকথাগুলোর মূল্য
কম নয়। আধুনিক শিক্ষার কর্মনাশা শ্বোতে সেগুলো বিস্মৃতির অতল গর্ভে তলিয়ে যাচ্ছে। এখনকার
শিক্ষিত জননী সন্তানকে আর রাখালের পিঠা গাছের কথা, রাক্ষসপুরীর ঘুমন্ত রাজকন্যার কথা বা
