তাতেই কাপড় তাতেই ভাত ।

প্রবাদ বাক্যে এবং ডাক ও খনার বচনে কত যুগের ভুয়োদর্শনের পরিপকৃ ফল সঞ্চিত হয়ে আছে,
কে তা অস্বীকার করতে পারে? শুধু তাই নয়, জাতির পুরনো ইতিহাসের অনেক গোপন কথাও
এর মধ্যে খুঁজে পাওয়া যায়।
আমরা আজও বলি- 'পিড়েয় বসে পেঁড়োর খবর ।' এই প্রবাদ বাক্যটি সেই সময়ের কথা মনে করিয়ে
দেয়, যখন পাগুয়া বঙ্গের রাজধানী ছিল। কে এই প্রবাদ বাক্য, ডাক, খনার বচনগুলি সংগ্রহ করে
তাদের চিরকাল জীবন্ত করে রাখবে?
তারপর ধরুন, ছড়ার কথা । কথায় কথায় ছেলেমেয়েগুলো ছড়া কাটতে থাকে ।রোদের সময় বৃষ্টি
হচ্ছে,অমনি তারা সমস্বরে ঝংকার দিয়ে ওঠে_

খেঁকশিয়ালীর বিয়ে হচ্ছে।
এর সঙ্গে সঙ্গে মনে করুন মায়ের সেই ঘুমপাড়ানী গান, সেই খোকা-খুকির ছড়া । এগুলি সরস প্রাণের

জীবন্ত উৎস, কিন্তু আজ দুঃখে দৈন্যে প্রাণে সুখ নেই। ছড়াও ক্রমে লোকে ভুলে যাচ্ছে। কে
এগুলিকে বইয়ের পাতায় অমর করে রাখবে?

শুধু ছড়া কেন? খেলাধুলার না কত বাধা গৎ আছে বা ছিল আমাদের এ দেশে । যখন ফুটবল, ব্যাটবলের নাম
কারও জানা ছিল না, তখন কপাটি খেলার খুব ধুম ছিল। সে খেলার সঙ্গে কত না বাধা বুলি ছেলেরা ব্যবহার
করত-_

এক হাত বোল্লা বার হাত শিং
উড়ে যায় বোল্লা ধা তিং তিং।

বিদেশি খেলার প্রচলনের সঙ্গে সঙ্গে এসব লোপ পাবার উপক্রম হয়েছে । কে এদের বাচিয়ে রাখবে?

তারপর ধরুন, পল্লিগানের কথা । পল্লিসাহিত্য সম্পদের মধ্যে এই গানগুলি অমূল্য রত্ুবিশেষ।
সেই জারি গান, সেই ভাটিয়ালি গান, সেই রাখালি গান, মারফতি গান- গানের এক অফুরন্ত ভাণ্ডার
ওতপ্রোতভাবে জড়িয়ে আছে। শহুরে গানের প্রভাবে সেগুলো এখন বর্বর চাষার গান বলে জদ্রসমাজে
আর বিকায় না। কিন্ত_

মনমাঝি তোর বৈঠা নে রে
আমি আর বাইতে পারলাম না।

এই গানটির সঙ্গে আপনার শহুরে গানের কোনো তুলনা হতে পারে? কিন্তু ধারাবাহিকরূপে সেগুলো
সংগ্রহের জন্য কোনো চেষ্টা হচ্ছে কি?

এ পর্যন্ত যা বললাম সেগুলো হচ্ছে পল্লির প্রাচীন সম্পদ । সাহিত্যের ভান্ডারে দান করবার মতো পল্লির
নতুন সম্পদেরও অভাব নেই। আজকাল বাংলাসাহিত্য বলে যে সাহিত্য চলছে, তার পনেরো আনা
হচ্ছে শহুরে সাহিত্য, সাধু ভাষায় বলতে গেলে নাগরিক সাহিত্য । সে সাহিত্যে আছে রাজ-রাজড়ার
কথা, বাবু-বিবির কথা, মোটরগাড়ির কথা, বিজলি বাতির কথা, সিনেমা থিয়েটারের কথা, চায়ের
বাটিতে ফুঁ দেবার কথা । এইসব কথা নিয়ে গল্প, উপন্যাস, কবিতা, নাটক রাশি রাশি লেখা হচ্ছে।
