### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ড. মুহম্মদ শহীদুল্লাহ পল্লিসাহিত্য সংরক্ষণের ওপর কেন এত জোর দিয়েছেন?**
> 💡 **উত্তর:** পল্লির লোকগাথা, ছড়া, প্রবাদ ও গীতিকার মধ্যে আবহমান বাংলার খাঁটি প্রাণ, সংস্কৃতি ও ঐতিহ্য লুকিয়ে আছে; আধুনিকতার আগ্রাসনে এগুলো হারিয়ে গেলে জাতীয় সংস্কৃতি বিপন্ন হবে।

> ❓ **প্রশ্ন: পল্লিসাহিত্য পুনরুদ্ধারে শহুরে শিক্ষিত সমাজের ভূমিকা কী হওয়া উচিত?**
> 💡 **উত্তর:** পল্লিঅঞ্চলে গিয়ে লোকগাথা ও ছড়াগুলো আধুনিক বৈজ্ঞানিক পদ্ধতিতে সংগ্রহ, সংরক্ষণ ও গবেষণার ব্যবস্থা করা শিক্ষিত সমাজের জাতীয় দায়িত্ব।
