### 📝 পাঠ-পরিচিতি : উদ্যম ও পরিশ্রম” নিবন্ধটি মোহাম্মদ লুৎফর রহমানের উন্নত জীবন গ্রন্থের দশম
পরিচ্ছেদ থেকে সংগৃহীত । গ্রন্থের মূল নিবন্ধে এর নাম “চাকরি, কাজকর্ম ও ব্যবসা : উদ্যম, চেষ্টা,
পরিশ্রম ।' উদ্যম ও পরিশ্রম নিবন্ধে লুৎফর রহমান স্পষ্টরূপে উচ্চারণ করেছেন যে, জীবনধারণের
জন্য কাজ করতে হবে। তবে কোনো কাজই যেন মনের স্বাধীনতাকে খর্ব না করে। চাকরি জীবনে
স্বার্থবুদ্ধি বা অন্যায়ের কোনো স্পর্শ যেন না থাকে। কাজ ছোট হোক ক্ষতি নেই, কিন্ত তা করতে
গিয়ে যেন ব্যক্তি তার সন্তার অমর্যাদা না ঘটায়। পৃথিবীতে এমনও দৃষ্টান্ত আছে, যারা এককালে
পৃথিবীখ্যাত লোক । আত্মোন্নতির জন্য পরিশ্রম এবং উদ্যম অপরিহার্য, এর সঙ্গে উন্নত দৃষ্টি ও
একাগ্র মনোযোগ থাকতে হবে। সন্তার মহিমা উদ্ভাসিত হয় কাজের মাধ্যমে, তেমনি সমাজেও
এই যে, উদ্যম ও পরিশ্রমের মাধ্যমে নিজেকে বিকশিত করা যায়; অন্যের অনুগ্রহ নয়, বরং নিজের
পরিশ্রম ও কাজের সূত্রে প্রতিষ্ঠিত হওয়াই জীবনের প্রকৃত সফলতা ।

কর্ম-অনুশীলন
১. সমাজ ও রাষ্ট্রীয় জীবনে পাচটি জনসেবামূলক কাজের উল্লেখ করো ।
২. তোমার এলাকায় তুমি কী কী সমাজসেবামূলক কাজ করতে পার তার তালিকা তৈরি করো ।

