### ✍️ মূল পাঠ্যবইয়ের নমুনা প্রশ্ন

বহুনির্বাচনি প্রশ্ন

১। উদ্যম ও পরিশ্রম" প্রবন্ধটি লেখকের কোন গ্রন্থ থেকে সংগৃহীত?
