রাস্তার সৌন্দর্যের দিকে কারও দৃষ্টি নাই, সৌন্দর্য নামক জিনিসটার দিকেই কারও দৃষ্টি নাই। গ্রামে
অনেকগুলি কোঠাবাড়ি আছে। সে সব প্রস্তুত করতে যথেষ্ট অর্থ ব্যয় হয়েছে। কিন্তু সৌন্দর্যানুভূতির
কোন নিদর্শন বাড়িগুলির ভিতরেও পাওয়া যায় না আর বাইরেও পাওয়া যায় না। এক কাঠা জমিও
কেউ সুন্দরভাবে সাজাতে চেষ্টা করেনি । কেউ হয়তো কিছু ফার্নিচার, দু'একখানা ছবি একটা ঘরে
রেখেছে। কিন্তু সে ঘরে প্রবেশ করলেই বোঝা যায়, যে গৃহস্বামী 18519 বা রুচি জিনিসটার সঙ্গে দূর
সম্পর্কও রাখে না। মাটির বাড়ির অবস্থা কোঠাবাড়ির চেয়েও শোচনীয়,আর বাগান, পুষক্ষরিণী প্রভৃতির
বিষয়ে কিছু না বলাই ভালো ।

পল্লিগ্রামের বিষয় যা বলা হলো, শহরের বেলাতেও তাই বলা চলে । শহরের ঘরবাড়ি, আসবাবপত্র,
বাড়ির ঝেষ্টনী প্রভৃতি দেখলে স্পষ্টই বোঝা যায় যে, আমাদের দেশবাসীরা জীবনে সৌন্দর্যের
প্রয়োজন মোটেই অনুভব করেন না, সুন্দর কি আর অসুন্দর কি সে বিষয়ে তাদের ধারণা একান্তই

কুহেলিকাবৃত।

হচ্ছে সেই বিরাট জীবন শিল্পেরই এক একটি বিভাগমাত্র। প্রত্যেকটি বিভাগের দিকে আমাদের দৃষ্টি
রাখা দরকার, জীবন-শিল্পকে সার্থক করার জন্যে । আর যদি সত্যই তা করতে হয়, তবে আমাদের
জীবনকে নিয়ন্ত্রণ করতে হবে, এক কথায় আমাদের জীবনের প্রত্যেকটি বিভাগকে নিয়ন্ত্রণ করতে
হবে। আর সেজন্য দরকার ব্যাপক এবং একান্তিক সমবায়িক প্রচেষ্টা ।


পাঠক বলবেন, এত বড়ো প্রচেষ্টার কথা বলা সহজ, করা সহজ নয়। ক্ষুদ্র আমি এতে কী করতে পারি?
তবে বলি শুনুন। আপনি এতে অনেক কিছু করতে পারেন। আপনার বাড়িকে সুন্দর করে সাজান।
আপনার বাড়ির উঠানকে, আশ-পাশের জমিকে পত্রেপুম্পে শোভিত করে তুলুন । আপনার পোশাক-
পরিচ্ছদ আর্টের এক একটি নিদর্শন হোক । সুন্দর এক বেষ্টনী আপনার জীবনে ঘিরে থাকুক।
সুন্দরের প্রশংসায় আপনার কণ্ঠ মুখরিত হোক। দেখবেন নিজেকে যতটা ক্ষুদ্র মনে করেছিলেন
ততটা ক্ষুদ্র আপনি নন। আর দেখবেন, আপনার স্তব-স্ততিতে, আপনার সাধনায় তুষ্ট হয়ে
সৌন্দর্যদেবী আপনার গ্রামে, আপনার পাড়ায় সশরীরে আবির্ভূত হয়েছেন ।

---

### 📚 শব্দার্থ ও টীকা : পদব্রজ - পায়ে হাটা। নর্দমা - পয়ঃপ্রণালি, ড্রেন। মজানদী - জলহীন নদী,
শুকিয়ে যাওয়া নদী। স্কীত - ফুলে বা ফেঁপে উঠেছে এমন, গর্বিত। কোঠাবাড়ি - পাকাবাড়ি,
অদ্টরালিকা, দালান। ফার্নিচার - আসবাবপত্র। কুহেলিকাবৃত - কুয়াশা আবৃত, প্রচ্ছন্ন। সমবায়িক-
সম্মিলিত উদ্যোগে কোনো কিছু গড়ে তোলার প্রয়াস, দলবদ্ধ প্রচেষ্টা ।

---

### 📝 পাঠ-পরিচিতি : বাংলা একাডেমি থেকে প্রকাশিত এস. ওয়াজেদ আলি রচনাবলি থেকে, “জীবনে শিল্পের
স্থান' শীর্ষক প্রবন্ধটি সংকলিত হয়েছে। সৃষ্টির সেরা জীব মানুষ । তবে মন না থাকলে মানুষ হয় না।
আর এ মনকে সর্বদা মানস-সৌন্দর্ষের চর্চায় নিবেদিত হতে হয় । কথাবার্তা, আচরণ, খাদ্য গ্রহণ,
করে তোলে । এর ফলে পরিবার, সমাজ, জাতি, দেশ নির্বিশেষে একটি সুদৃঢ় ব্যবস্থাপনার নিদর্শনরূপে
গড়ে ওঠে । “জীবনে শিল্পের স্থান' প্রবন্ধটিতে এস. ওয়াজেদ আলি জীবন ও সৌন্দর্যবোধের সম্পর্ক
দেখিয়েছেন । প্রবন্ধটি সৌন্দর্য বোধে উদ্বুদ্ধ হবার শিক্ষা দেয় ।

কর্ম-অনুশীলন
তোমার বাড়ির সৌন্দর্য বাড়াতে তুমি কী কী পদক্ষেপ নিয়েছ তার একটি তালিকা তৈরি করো ।

