### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: এস ওয়াজেদ আলির মতে জীবনে শিল্পের প্রয়োজনীয়তা কী?**
> 💡 **উত্তর:** শিল্প মানুষের রুচিকে পরিশীলিত করে, জীবনকে সুন্দর ও অর্থবহ করে তোলে এবং যান্ত্রিক জীবনের শুষ্কতা দূর করে মানবিক মূল্যবোধ ও আনন্দের সঞ্চার করে।

> ❓ **প্রশ্ন: শিল্প ও দৈনন্দিন জীবনের সম্পর্ক কী?**
> 💡 **উত্তর:** শিল্প কেবল ধনীর বিলাসিতা নয়; সাধারণ মানুষের নিত্যদিনের কাজ, বাসস্থান ও ব্যবহারের মধ্যেও সৌন্দৰ্যবোধ ও শিল্পচেতনার প্রকাশ ঘটা সম্ভব।
