# ১১তম অধ্যায়: আম-আঁটির ভেঁপু (বিভূতিভূষণ বন্দ্যোপাধ্যায়)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: বিভূতিভূষণ বন্দ্যোপাধ্যায়*

---

### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি: বিভূতিভূষণ বন্দ্যোপাধ্যায় ১৮৯৪ খিষ্টাব্দে ২৪ পরগনার মুরারিপুর গ্রামে জনুগ্রহণ
করেন। স্থানীয় বনগ্রাম স্কুল থেকে ১৯১৪ খিষ্টাব্দে তিনি ম্যাট্রিক পাশ করেন এবং কলকাতা রিপন কলেজ
থেকে আইএ এবং বিএ ডিগ্রি লাভ করেন। কর্মজীবনে তিনি হুগলী, কলকাতা ও ব্যারাকপুরের বিভিন্ন
স্কুলে শিক্ষকতা করেন। প্রাকৃতিক সৌন্দর্য ও গ্রামবাংলার সাধারণ মানুষের সহজ-সরল জীবন-যাপনের
অসাধারণ এক আলেখ্য নির্মাণ করে তিনি বাংলা কথাসাহিত্যে অমর হয়ে আছেন। প্রকৃতি এবং মানুষের
জীবনের অভিন্ন সম্পর্কের চিরায়ত তাৎপর্ষে তাঁর কথাসাহিত্য মহিমামগ্তিত । বিভূতিভূষণ বন্দ্যোপাধ্যায়ের
উল্লেখযোগ্য উপন্যাস হলো : পথের পাঁচালী, অপরাজিত, আরণ্যক, ইছামতি, দৃষ্টি্রদীপ | গল্পগ্রন্থ :
মেঘমল্লার , মৌরীফুল, যাত্রাবদল । ১৯৫০ খিষ্টাব্ের ১লা সেপ্টেম্বর তিনি মৃত্যুবরণ করেন |

