এই সময়ে মেয়ে দুর্গা কোথা হইতে পা টিপিয়া টিপিয়া আসিয়া বাহিরের দুয়ারের আড়াল হইতে
সতর্কতার সহিত একবার উকি মারিল এবং অপর পক্ষ সম্পূর্ণ সজাগ দেখিয়া ওধারে পাঁচিলের
বন্ধ আছে। এদিকে রোয়াকে দীড়ানো অসম্ভব, রৌদ্বের তাপে পা পুড়িয়া যায়, কাজেই সে স্থান
হইতে নামিয়া গিয়া উঠানের কীঠালতলায় দীড়াইল। রৌদ্বে বেড়াইয়া তাহার মুখ রাঙা হইয়া উঠিয়াছে,
আচলের খুঁটে কী কতকগুলো যত্ন করিয়া বাধা । সে আসিয়াছিল এইজন্য যে, যদি বাহিরের দুয়ার
খোলা পায় এবং মা ঘুমাইয়া থাকে, তবে ঘরের মধ্যে চুপি চুপি ঢুকিয়া একটু শুইয়া লইবে। কিন্তু
বাবার, বিশেষত মার সামনে সম্মুখ দুয়ার দিয়া বাড়ি ঢুকিতে তাহার সাহস হইল না।

উঠানে নামিয়া সে কীঠালতলায় দীড়াইয়া কী করিবে ঠিক করিতে না পারিয়া নিরুৎসাহভাবে এদিক ওদিক
চাহিতে লাগিল । পরে সেখানেই বসিয়া পড়িয়া আচলের খুঁট খুলিয়া কতকগুলি শুকনো রড়া ফলের বিচি
বাহির করিল । খানিকক্ষণ চাহিয়া থাকিয়া সে আপন মনে সেগুলি গুনিতে আরভ্ত করিল, এক-দুই-
তিন-চার ... ছাব্বিশটা হইল । পরে সে দুই তিনটা করিয়া বিচি হাতের উল্টা পিঠে বসাইয়া উচু
অপুকে এইগুলো দেবো - আর এইগুলো পুতুলের বাক্সে রেখে দেবো-_

কেমন বিচিগুলি তেল চুকচুক কচ্ছে- আজই গাছ থেকে পড়েচে, ভাগ্যিস আগে গেলাম, নৈলে সব
গোরুতে খেয়ে ফেলে দিতো, ওদের রাঙি গাইটা একেবারে রাক্স, সব জায়গায় যাবে, সেবার
কতকগ্তলো এনেছিলাম আর এইগুলো নিয়ে অনেকগুলো হলো ।

সে খেলা বন্ধ করিয়া সমস্ত বিচি আবার সযত্রে জীচলের খুঁটে বাধিল। পরে হঠাৎ কী ভাবিয়া রুক্ষ
চুলগুলি বাতাসে উড়াইতে উড়াইতে মহা খুশির সহিত পুনরায় সোজা বাটীর বাহির হইয়া গেল।

