### 📝 পাঠ-পরিচিতি: “আম-আঁটির ভেপু" শীর্ষক রচনাটি বিভূতিভূষণ বন্দ্যোপাধ্যায়ের পথের পাঁচালী উপন্যাসের
রচিত হয়েছে। অপু ও দুর্গা হতদরিদ্র পরিবারের শিশু। কিন্তু তাদের শৈশবে দারিত্যের সেই কষ্ট প্রধান
হয়ে ওঠেনি। গ্রামীণ ফলফলাদি খাওয়ার আনন্দ এবং বিচিত্র বিষয় নিয়ে তাদের বিস্ময় ও কৌতুহল
এখানে শিশুর আনন্দপূর্ণ শৈশব এবং প্রকৃতির সম্পর্ক দেখিয়েছেন বিভূতিভূষণ বন্দোপাধ্যায়। রচনাটি
শিশু-কিশোরকে প্রকৃতিমুখী হওয়ার প্রেরণা জোগায় ।

কর্ম-অনুশীলন

১. 'আম-আঁটির ভেপু* রচনায় যে সকল গ্রামীণ উপাদান ও শব্দ ব্যবহৃত হয়েছে তার একটি তালিকা তৈরি করো ।

২. তোমার পঠিত “আম-আঁটির ভেঁপু' অনুরূপ গ্রামীণ জীবনের বর্ণনা সংবলিত অন্য একটি গল্পের
আলোচনা লিখে শ্রেণিশিক্ষকের নিকট জমা দাও ।

