# ১২তম অধ্যায়: মানুষ মুহম্মদ (স.) (মোহাম্মদ ওয়াজেদ আলী)

**বাংলা সাহিত্য • নবম-দশম শ্রেণি (NCTB ২০২৬ শিক্ষাক্রম)**
*গদ্য বিভাগ — রচয়িতা: মোহাম্মদ ওয়াজেদ আলী*

---

### ✍️ লেখক-পরিচিতি
> লেখক-পরিচিতি : মোহাম্মদ ওয়াজেদ আলী ১৮৯ খিষ্টাব্দে (২৯ শে ভাদ্র ১৩০৩ বঙ্গাব্দ) সাতক্ষীরা জেলার
বাশদহ গ্রামে জন্গগ্রহণ করেন। কলকাতা বঙ্গবাসী কলেজে বিএ ক্লাসের ছাত্র থাকাকালীন তিনি অসহযোগ
আন্দোলনে যোগদান করেন এবং এখানেই লেখাপড়ার সমাপ্তি ঘটান। এরপর তিনি সাংবাদিকতাকে পেশা
হিসেবে গ্রহণ করেন। তিনি মাসিক মোহাম্মাদী, দেনিক মোহাম্মাদী, দৈনিক সেবক, সাগ্তাহিক সওগাত,
রচনার অন্যতম বৈশিষ্ট্য । স্বাস্থ্যগত কারণে তিনি ১৯৩৫ খিষ্টাব্দে কলকাতা ছেড়ে বাশদহে ফিরে আসেন
এবং সেখানেই ১৯৫৪ খিষ্টাব্দের ৮ই নভেম্বর মৃত্যুবরণ করেন। 

---

## 📖 মূল পাঠ (গদ্য)

মোহাম্মদ ওয়াজেদ আলী



হজরতের মৃত্যুর কথা প্রচারিত হইলে মদিনায় যেন আধার ঘনাইয়া আসিল। কাহারও মুখে আর কথা
সরে না; কেহবা পাগলের মতো কাণ্ড শুরু করে। রাসুলুল্লাহর পীড়ার খবর শুনিবার জন্য বহুলোক
লইয়া লাফাইয়া উঠিলেন, যে বলিবে হজরত মরিয়াছেন, তাহার মাথা যাইবে ।

মহামতি আবুবকর শেষ পর্যন্ত হজরতের মৃত্যুশয্যার পার্থে ছিলেন। তিনি গন্তীরভাবে জনতার
মধ্যে দাড়াইলেন। বলিলেন, যাহারা হজরতের পূজা করিত, তাহারা জানুক তিনি মারা গিয়াছেন;
বাণী: মুহম্মদ (স.)একজন রাসুল বৈ আর কিছু নন। তাহার পূর্বে আরও অনেক রাসুল মারা গিয়াছেন।
রাসুলুল্লাহ (স.) মরিতে পারেন, নিহত হইতে পারেন; তাই বলিয়া তিনি যেই সত্য তোমাদের দিয়া
গেলেন তাহাকে কি তোমরা মাথা পাতিয়া গ্রহণ করিবে না? এই বিশ্বভুবনে এ দূর অন্তরীক্ষে যাহা
কিছু দেখিতে পাও সবই আল্লাহ্‌র সৃষ্টি, তাহারই দিকে সকলের মহাযাত্রা।

লুটাইল। তাহার স্মরণ হইল হজরতের বাণী : আমি তোমাদেরই মতো একজন মানুষ মাত্র।
তাহার মনে পড়িল কুরআনের আয়াত : মুহম্মদ, মৃত্যু তোমারও ভাগ্য, তাহাদেরও ভাগ্য।
তাহার অন্তরে ধ্বনিয়া উঠিল মুসলিমের গভীর প্রত্যয়ের স্বীকারোক্তি অমর সাক্ষ্য : মুহম্মদ (স.)
আল্লাহর দাস (মানুষ) ও রাসুল ।

শোকের প্রথম প্রচণ্ড আঘাতে আত্মবিস্মৃতির পূর্ণ সম্ভাবনার মধ্যে দাঁড়াইয়া স্থিতধী হজরত আবুবকর
(রা.) রাসুলের প্রতি শ্রদ্ধা নিবেদনের সীমারেখা সৃষ্টি করিয়া তুলিলেন। তিনি রাসুল, কিন্তু তিনি মানুষ,
আমাদেরই মতো দুঃখ-বেদনা, জীবন-মৃত্যুর অধীন রক্ত-মাংসে গঠিত মানুষ- এই কথাই বৃদ্ধ হজরত
আবুবকর সিদ্দিক রো.) মুর্ছিত মুসলিমকে বুঝাইয়া দিলেন ।

তিনি মানুষের মন আকর্ষণ করিয়াছিলেন মুখ্যত তাহার মানবীয় গুণাবলি ছারা । মক্কার শ্রেষ্ঠ বংশে
তিনি জন্মিয়াছিলেন। কিন্তু বংশগৌরব হজরতের সচেতন চিন্তে মুহূর্তের জন্যও স্থানলাভ করে নাই।



জন্দুঃখী হইয়া তিনি সংসারে আসিয়াছিলেন। এই দুঃখের বেদনা তাহার দেহসৌন্দর্য ও চরিত্র-
মাধুরীর সহিত মিলিয়া তাহাকে নরনারীর একান্ত প্রিয় করিয়া তুলিয়াছিল। আবাল্য তিনি ছিলেন আল-
আমিন- বিশ্বস্ত, প্রিয়ভাষী, সত্যবাদী । তাহার অসাধারণ যোগ্যতা, বুদ্ধি, বিচারশক্তি, বলিষ্ঠ দেহ
দেখিয়া মানুষ অবাক হইয়া যাইত । এই সকল গুণ বিবি খাদিজাকে আকর্ষণ করিয়াছিল ।

বস্তুত হজরতের রূপলাবণ্য ছিল অপূর্ব, অসাধারণ । মক্কা হইতে মদিনায় হিজরতের পথে এক
ব্রত। হজরত যখন আসিলেন, কুটিরস্বামী আবু মা*বদ মেষপাল চরাইতে গিয়াছিলেন। তাহার পত্রী
উম্মে মা'বদ ছাগীদুগ্ধ দিয়া হজরতের তৃষ্তা দূর করিলেন। গৃহপতি ফিরিলে এই নারী স্বামীর কাছে নব
অতিথির রূপ বর্ণনা করেন, সুন্দর, সুদর্শন পুরুষ তিনি। তাহার শীর্ষে সুদীর্ঘ কুঞ্চিত কেশপাশ, বয়ানে
অপূর্ব কান্তশ্রী। তাহার আয়তকৃষ্ণ দুটি নয়ন, কাজল-রেখার মতো যুক্ত যুগল, তাহার সুউচ্চ গ্রীবা,
কালো কালো দুটি চোখের ঢলঢল চাহনি মনপ্রাণ কাড়িয়া নেয়। গুরুগন্তীর তাহার নীরবতা, মধুবর্ধী
তাহার মুখের ভাষণ, বিনীত নম্র তাহার প্রকৃতি । তিনি দীর্ঘ নন, খর্ব নন, কৃশ নন। এক অপূর্ব
পুলকদীপ্তি তাহার চোখেমুখে, বলিষ্ঠ পৌরুষের ব্যঞ্জনা তাহার অঙ্গে। বড়ো সুন্দর, বড়ো মনোহর সেই
অপরূপ রূপের অধিকারী ।

তাহার সবটুকু তিনি পাইয়াছিলেন। সত্যের নিবিড় সাধনায় তাহার চরিত্র মধুময় হইয়া উঠিয়াছিল।
হইয়াছিলেন। শত্রুর নিষ্ঠুরতম নির্যাতন তাহার অন্তরের লৌহকপাটে আহত হইয়া ফিরিয়া যাইত।
কিন্ত সত্যে তিনি বজ্ের মতো কঠিন, পর্বতের মতো অটল হইলেও করুণায় তিনি ছিলেন কুসুমকোমল ।
বৈরীর অত্যাচারে বারবার তিনি জর্জরিত হইয়াছিলেন, শত্রুর লোস্ট্রাঘাতে-অরাতির হিংস্র আক্রমণে
বরাঙ্গের বসন তাহার বহুবার রক্তরঙিন হইয়া উঠিয়াছে, তথাপি পাপী মানুষকে তিনি
ভালোবাসিয়াছিলেন, অভিশাপ দেওয়ার চিন্তাও তাহার অন্তরে উদিত হয় নাই। মক্কার পথে প্রান্তরে
পৌন্তলিকের প্রস্তরঘায়ে তিনি আহত হইয়াছেন, ব্যঙ্গবিদ্ধপে বারবার তিনি উপহাসিত হইয়াছেন; কিন্ত
তাহার অন্তর ভেদিয়া একটি মাত্র প্রার্থনার বাণী জাগিয়াছেঃ-এদের জ্ঞান দাও প্রভু, এদের ক্ষমা কর।

দেখিয়াছি। পথ চলিতে শত্রুর প্রস্তরঘায়ে তিনি অবসন্ন হইয়া পড়িতেছিলেন; তখন তাহারাই আবার
তাহাকে তুলিয়া দিতেছিল। তিনি পুনর্বার চলা শুরু করিলে দ্বিগুণ তেজে পাথরবৃষ্টি করিতেছিল। রক্তে
রক্তে তাহার সমস্ত বসন ভিজিয়া গিয়াছে, দেহ নিঃসৃত রুধিরধারা পাদুকায় প্রবেশ করিয়া জমিয়া শক্ত
হইয়াছে, মৃত্যুর আবছায়া তাহার চৈতন্যকে সমাচ্ছন্ন করিবার চেষ্টা করিতেছে, তথাপি অত্যাচারীর
বিরুদ্ধে তাহার বিন্দুমাত্র অভিযোগ নাই। রমণীর রূপ, গৃহস্থের ধনসম্পদ, নেতৃত্বের মর্যাদা, রাজার
সিংহাসন সব কিছুকে তুচ্ছ করিয়া সেই সত্যকে তিনি জীবনের শ্রেষ্ঠতম সম্বল জ্ঞানে আশ্রয়
করিয়াছিলেন; তাহাকে উপহাসিত, অবহেলিত, অস্বীকৃত দেখিয়াও ক্রোধ, ঘৃণা বা বিরক্তির একটি
শব্দও তাহার মুখে উচ্চারিত হয় নাই । অভিসম্পাত করিতে অনুরুদ্ধ হইয়াও তিনি বলিলেন : না না,
তাহা কখনই সম্ভব নয়। এই পৃথিবীতে আমি ইসলামের বাহন, সত্যের প্রচারক। মানুষের দ্বারে

দ্বারে সত্যের বাণী বহন করা আমার কাজ। আজ যাহারা সত্যকে অস্বীকার করিতেছে, তাহাকে
মারিতে উদ্যত হইয়াছে, হয়ত কাল তাহারা-তাহাদের অনাগত বংশধরেরা ইসলাম কবুল করিবে ।
আপনার আঘাত জর্জরিত দেহের বেদনায় তিনি কাতর । সত্যকে ব্যাহত দেখিয়া মনের ব্যথা তাহার
সেই কাতরতাকে ছাপাইয়া উঠিল। তিনি উ্ধ্বদিকে বাহু প্রসারণ করিয়া বলিলেন : তোমার পতাকা
যদি দিয়াছ প্রভু, হীন আমি, তুচ্ছ আমি, নির্বল আমি, তাহা বহন করিবার শক্তি আমায় দাও ।
বিপদবারণ তুমি অশরণের শরণ তুমি, তোমার সত্য মানুষের দ্বারে পৌছাইয়া তাহাকে উন্নীত করিলেন
ষাহারা- তাহাদের পংক্তিতে আমার স্থান দাও।

মক্ধাবাসীরা হজরতের নবিতৃ লাভের শুরু হইতেই তাহার প্রতি কী নির্মম অমানুষিক অত্যাচার চালাইয়াছিল,
আমরা দেখিয়াছি। যখন তাহাদের নির্যাতন সহনাতীত হইল, যখন দেখা গেল, কোরেশরা সত্যকে গ্রহণ
আবুবকরের ছিন্ন মুণ্ড আনিবার জন্য বিপুল পুরস্কারের লোভ দেখাইয়া, ক্ষুধার্ত ব্যাঘ্ের মতো হিং
শত শত ঘাতক পাঠানো হইল। বদর, ওহোদ ও আহজাব (বা খন্দক) যুদ্ধে মক্কার বাসিন্দা এবং
ফেলিবার জন্য প্রাণপণ করিল । খয়বরের যুদ্ধে হজরতের পরাজয়ের মিথ্যা সংবাদ শুনিয়া হজরতের
মৃত্যু সম্ভাবনায় আনন্দে আত্মহারা হইয়া পড়িল। হুদায়বিয়া সন্ধিতে হজরতের শান্তিপ্রিয়তার সুযোগ
লইয়া মুসলিমের ক্কন্ধে ঘোর অপমানের শর্ত চাপাইয়া দেওয়ার পরও তাহাদের সহিত
বিশ্বাসঘাতকতা করিতে চাহিল এবং তারপর হজরত যেই দিন বিজয়ী বেশে মক্কায় প্রবেশ করিলেন,
হানিল বৈরিতার বিষাক্ত বাণ, হজরত তাহাদের সহিত কী ব্যবহার করিলেন? জয়ীর আসনে বসিয়া
ন্যায়ের তুলাদণ্ড হাতে লইয়া বলিলেন : ভাইসব, তোমাদের সম্বন্ধে আমার আর কোনো অভিযোগ
নাই, আজ তোমরা সবাই স্বাধীন, সবাই মুক্ত। মানুষের প্রতি প্রেমপুণ্যে উদ্ভাসিত এই সুমহান
প্রতিশোধ সম্ভব করিয়াছিল হজরতের বিরাট মনুষ্যতৃ।

শুধু প্রেম-করুণায় নয়, মানুষ হিসেবে আপনার তুচ্ছতাবোধ আপনার ক্ষুদ্রতার অনুভূতি
কাছে আসিয়া ভয়ে কীপিতে লাগিল। হজরত স্মিতমুখে তাহাকে বলিলেন, কেন তুমি ভয় পাইতেছ?
ভয়ের কিছুই এখানে নাই । আমি রাজা নই, সম্রাট নই, মানুষের প্রভূ নই। আমি এমন এক নারীর
সন্তান, সাধারণ শুল্ক মাংসই ছিল যাহার নিত্যকার আহার্য।

ও স্বচ্ছ রাখিয়াছিল। মানুষ ত্রুটির অধীন, হজরতও মানুষ, সুতরাং তাহারও ত্রুটি হইতে পারে- এই
যুক্তির বলে নয়, বরং তাহার অনাবিল চরিত্রের স্বচ্ছ সহজ প্রকাশ মর্ষাদাহানির আশঙ্কা তুচ্ছ করিয়া,



একদিন তিনি মক্কার সন্ত্রান্ত লোকদের কাছে সত্য প্রচারে ব্রতী । মজলিসের এক প্রান্তে বসিয়া
একটি অন্ধ । সম্ভবত সে হজরতের দুইএকটি কথা শুনিতে পায় নাই। বক্তৃতার মাঝখানে একটি
প্রশ্ন করিয়া সে হজরতকে থামাইল। বাধা পাইয়া হজরতের মুখে ঈষৎ বিরক্তির আভাস ফুটিয়া উঠিল,
তাহার ললাট সামান্য কুঞ্চিত হইল ।

ব্যাপারটি এমন কিছুই গুরুতর নয়। বক্তৃতায় বাধা হইলে বিরক্তি অতি স্বাভাবিক। আবার দুঃখী
করিয়াছেন, কাঙাল বলিয়া তাহাকে হেলা করিয়াছেন, এই কথা কাহারও মনে আসে নাই। কিন্তু
তাহার এই তুচ্ছতম ত্রুটির প্রতি ইঙ্গিত আসিল কুরআনের একটি বাণীতে ৷ তিনি বিনা দ্বিধায়, বিনা

মানুষ হিসেবে যে ক্ষুদ্রতাবোধ, মানুষের সহজ দৈন্যের যে নির্মল অনুভূতি হজরতকে আপনার
দোষক্রটি সাধারণের চক্ষে এমন নির্বিকারভাবে ধরাইয়া দিতে প্ররোচিত করিয়াছিল, তাহাই আবার
তাহার মহিমান্বিত জীবনে ইচ্ছা-স্বীকৃত দারিদ্রের মাঝখানে প্রদীপ হইয়া জুলিয়াছিল। অনাত্ীয় পরিপার্শ্ের
মধ্যেও নিবিড় নির্বিচার ভক্তি, শ্রদ্ধা, স্বীকৃতি ও আনুগত্য তিনি বড়ো অল্প পান নাই । শত শত, বরং সহস্র
সহস্র মুসলিম তাহার ব্যক্তিগত পারিবারিক সুখ-স্বাচ্ছন্দ্যের উপকরণ সংগ্রহ করিয়া দিতে সর্বদা শুধু
ইচ্ছুক নয়, সমুৎসুক ছিল। কিন্ত হজরত আপনাকে দশজন মানুষের মধ্যে একজন গণনা করিলেন,
সকলের সঙ্গী সহচররূপে সহোদর ভাইয়ের মতাদর্শ প্রয়াসী নেতার কর্তব্য পালন করিলেন। সত্যের
দেশের রাজা-মানুষের মনের রাজা হইয়া স্বেচ্ছায় দারিদ্র্যের কণ্টক মুকুট মাথায় পরিলেন। তাই
তাহার গৃহে সকল সময় অন্ন জুটিত না, নিশার অন্ধকারে প্রদীপ জ্বালিবার মতো তৈলটুকুও সময়
সময় মিলিত না। এমনি নিঃস্ব কাঙালের বেশে মহানবি মৃত্যু রহস্যের দেশে চলিয়া গেলেন।

স্বামীর মহাপ্রয়াণে বিয়োগবিধুরা আয়েশার বক্ষ ভেদিয়া শোকের মাতম উঠিল, মানুষের মঙ্গল সাধনায়
যিনি অতন্দ্র রজনী যাপন করিলেন, সেই সত্যাশ্য়ী আজ চলিয়া গেলেন। নিঃস্বতাকে সম্বল
করিয়া যিনি বিশ্বমানবের জন্য আপনাকে বিলাইয়া দিলেন, তিনি আজ চলিয়া গেলেন। সাধনার
পথে শক্রর আঘাতকে যিনি অস্্ান বদনে সহিলেন। হায়, সেই দয়ার নবি, মানুষের মঙ্গল বহিয়া
আনিবার অপরাধে প্রস্তরঘায়ে যাহার দীত ভাঙিয়াছিল, প্রশস্ত ললাট রুধিরাক্ত হইয়াছিল, আর সেই
জীবন-নদীর ওপারে চলিয়া গেলেন। দুই বেলা পূর্ণোদর আহারও যাহার ভাগ্যে হয় নাই, ত্যাগ ও
তিতিক্ষার মূর্ত প্রকাশ মহানবি আজ চলিয়া গেলেন । বিবি আয়েশার মর্মছেড়া এই বিলাপ সমস্ত
মানুষের, সমগ্র বিশ্বের । শুধু সত্য সাধনায় নয়, শুধু উধ্ব লোকচারী মহাব্রতীর তত্বানুসন্ধানে নয়,
মানুষের সঙ্গে মানুষের ব্যবহারে হযরত মোস্তফা ইতিহাসের একটি অত্যন্ত অসাধারণ চরিত্র। ত্যাগ,
প্রেম, সাধুতা, সৌজন্য, ক্ষমা, তিতিক্ষা, সাহস, শৌর্, অনুগ্হ, আত্মবিশ্বাস, তীক্ষ দৃষ্টি ও সমদর্শন

একজন হইয়াও তিনি দুর্লভ, আমাদের অতি আপনজন হইয়াও তিনি অনুকরণীয়, বরণীয় |

---

### 📚 শব্দার্থ ও টীকা : বীরবাহু-শক্তিধারী । স্থিতধী-স্থিরবুদ্ধিসম্পন্ন। ধী-বুদ্ধি। রাসুল-আল্লাহ্‌র প্রেরিত
পুরুষ ৷ পরহিতব্তী-পরের উপকারে নিয়োজিত। বয়ান মুখের বাণী। গ্রীবা-ঘাড়।
অকুতোভয়-নির্ভয়। নির্যাতন-অত্যাচার, জুলুম । কুসুমকোমল-ফুলের মতো নরম। লোন্ত্রাঘাত-
টিলের আঘাত। বৈরী-শক্র। অরাতি-শক্র। পৌত্তলিক-মূর্তিপূজক। তিতিয়া-ভিজে। সমাচ্ছন্ন-
অভিভূত। পুর্ণোদর-ভরপেট । বীরবাহু ওমর-ইসলামের দ্বিতীয় খলিফা হজরত ওমর (রা.) ছিলেন
একজন তেজস্বী বীরযোদ্ধা। ইসলাম গ্রহণের পূর্বে কোরেশ বংশোদ্ভূত তরুণ বীর ওমর মহানবিকে
হত্যা করার সংকল্প নিয়ে যখন যাচ্ছিলেন তখন তার ভগ্মীর কণ্ঠে পবিত্র কুরআনের বাণী শুনে তিনি
ইসলাম ধর্ম গ্রহণ করেন। হজরত ওমর (রা) ছিলেন একজন বীরযোদ্ধা, ন্যায়পরায়ণ শাসক ও
মহানবির বিশ্বাসভাজন সাহাবি |

রুধিরাক্ত- রক্তাক্ত, রক্তরঞ্জিত। রাহী-পথিক, মুসাফির । পুলকদীপ্তি-আনন্দের উদ্ভাস। অনুরুদ্ধ-অনুরোধ
করা হয়েছে এমন ।

মহামতি আবুবকর-ইসলামের প্রথম খলিফা এবং ইসলাম ধর্ম গ্রহণকারীদের মধ্যে প্রথম পুরুষ ব্যক্তি।

তিনি ছিলেন মহানবির হিজরতকালীন সঙ্গী এবং সারাজীবনের বিশ্বস্ত সহচর । তিনি ছিলেন সত্যনিষ্ঠ,

আদর্শবাদী ও ইসলামের জন্য নিবেদিতপ্রাণ ।

মক্কা-সৌদি আরবের অন্যতম প্রধান নগরী । এখানে আল্লাহর ঘর কাবা শরিফ অবস্থিত । এই
নগরীতে রাসুলুল্লাহ সে.) জনুগ্রহণ করেন।

মদিনা- সৌদি আরবে অবস্থিত মুসলিম বিশ্বের দ্বিতীয় সম্মানিত নগরী । এখানে হজরত মুহম্মদ (স.)
এবং হযরত আবু বকর (রা.) এর মাজার রয়েছে।

হিজরত- শাব্দিক অর্থ পরিত্যাগ ৷ এখানে মক্কা ত্যাগ করে মদিনা যাত্রা বোঝানো হয়েছে । এই সময়
থেকে হিজরি সাল গণনার শুরু ।

তায়েফ- সৌদি আরবের দক্ষিণাঞ্চলের একটি উর্বর প্রদেশ ।

বদর, ওহোদ, আহযাব, খয়বর- হজরতের জীবনকালে ভিন ধর্মাবলম্বলীদের বিরুদ্ধে এ সব
স্থানে মুসলমানদের যুদ্ধ হয়েছিল ।

হুদায়বিয়া- একটি যুদ্ধক্ষেত্র, এই স্থানে ভিন্ন ধর্মাবলম্বীদের সঙ্গে রাসুলুল্লাহ (স.) এর একটি সন্ধিপত্র
স্বাক্ষরিত হয় । এ সন্ধি ছিল অত্যন্ত গুরুত্বপূর্ণ এবং রাসুলুল্লাহর রাজনৈতিক দূরদর্শিতার পরিচায়ক।
খালিদ_ হজরতের জীবিতকালে ইসলামের প্রখ্যাত বীরযোদ্ধা এবং সেনাপতি ।

সাফা_ সাফা ও মারওয়া দুটি ছোটো পাহাড় কাবার নিকটে অবস্থিত। হজরত ইবরাহিম (আ.)-এর
স্ত্রী বিবি হাজেরা শিশুপুত্র ইসমাইলের পিপাসা নিবারণের জন্য পানির সন্ধানে এই দুই পাহাড়ের
মধ্যে ছোটাছুটি করেছিলেন। সেই স্মৃতি রক্ষার্থে আজও হজব্রতীরা সাফা-মারওয়ায় দৌড়ে থাকেন।
আয়েশা (রা.)_ হজরত আবুবকরের কন্যা, রাসুলুল্লাহ (স.)-এর অন্যতম সহধর্মিণী, বিদুষী রমণী



