### ❓ পাঠভিত্তিক প্রশ্ন ও উত্তর (Comprehension Q&A)

> ❓ **প্রশ্ন: ‘মানুষ মুহম্মদ (স.)’ প্রবন্ধে মহানবীর কোন গুণাবলি বিশেষভাবে চিত্রিত হয়েছে?**
> 💡 **উত্তর:** হজরত মুহম্মদ (স.)-এর ক্ষমাশীলতা, ধৈর্য, নিরহংকার জীবনযাপন, শত্রুর প্রতি দয়া এবং মানুষ হিসেবে তাঁর অতুলনীয় মানবিক সংবেদনশীলতা চিত্রিত হয়েছে।

> ❓ **প্রশ্ন: মক্কা বিজয়ের পর মহানবী (স.) শত্রুদের প্রতি কেমন আচরণ করেছিলেন?**
> 💡 **উত্তর:** তিনি চরম অত্যাচারী শত্রুদেরও কোনো প্রতিশোধ না নিয়ে ক্ষমা করে দিয়ে বলেছিলেন, 'আজ তোমাদের বিরুদ্ধে আমার কোনো অভিযোগ নেই, তোমরা সবাই মুক্ত।'
